/* Painel da plataforma (superadmin) — app/admin/. Telas: Visão geral · Pagamentos · Negócios (+ detalhe com abas) · Criar/Importar ·
   Exportar · Chatbots (Forja) · Chaves · Auditoria. Dados por A.api (api.js). Reutiliza CF.icon/CF.modal/CF.confirm/CF.toast/CF.download
   do core.js (carregado só pelos utilitários; CF.boot não é chamado). Preços para o MRR: CF.config.prices (um lugar só). */
(function () {
  "use strict";
  const CF = window.CF, A = window.A, esc = CF.esc, I = CF.icon, $ = (s, r = document) => r.querySelector(s);
  const money = (n) => "R$ " + Number(n || 0).toLocaleString("pt-BR", { minimumFractionDigits: 0, maximumFractionDigits: 2 });
  const when = (d, t = false) => (d ? new Date(d).toLocaleString("pt-BR", t ? { dateStyle: "short", timeStyle: "short" } : { dateStyle: "short" }) : "—");
  const PRICE = () => (CF.config && CF.config.prices) || { pro: 79 };
  const monthlyOf = (bl) => (!bl || !["active", "trialing", "past_due"].includes(bl.status) ? 0 : +bl.amount > 0 ? (bl.interval === "year" ? bl.amount / 12 : +bl.amount) : bl.interval === "year" ? ((PRICE().proYear || PRICE().pro * 12)) / 12 : PRICE().pro);
  const planPill = (b) => `<span class="pill ${b.plan && b.plan !== "free" ? "" : "gray"}">${b.plan && b.plan !== "free" ? I("crown") : ""}${esc({ free: "Free", pro: "Pro", business: "Pro", multi: "Pro" }[b.plan] || b.plan || "Free")}${b.trial ? " · teste" : ""}</span>`;
  const subPill = (bl) => { if (!bl || !bl.status) return `<span class="pill gray">sem assinatura</span>`;
    const m = { active: ["green", "ativa"], trialing: ["green", "em teste"], past_due: ["red", "pagamento atrasado"], canceled: ["gray", "cancelada"], unpaid: ["red", "não paga"], incomplete: ["amber", "aguardando pagamento"], incomplete_expired: ["gray", "expirada"], paused: ["gray", "pausada"] }[bl.status] || ["gray", bl.status];
    return `<span class="pill ${m[0]}">${esc(m[1])}</span>${bl.cancel_at_end && ["active", "trialing", "past_due"].includes(bl.status) ? ` <span class="pill amber">cancela no fim do período</span>` : ""}`; };
  const forjaPill = (f) => !f ? `<span class="pill gray">sem chatbot</span>` : `<span class="pill ${f.status === "ok" ? "green" : f.status === "error" ? "red" : "gray"}" title="${esc(f.last_error || "")}">${I("zap")}${esc({ ok: "no ar", error: "com erro", pending: "aguardando", off: "desligado" }[f.status] || f.status)}</span>`;
  const err = (m) => `<div class="alert err" style="background:var(--err-50);color:var(--err-700);border-radius:10px;padding:10px 12px">${esc(m)}</div>`;
  const srcNote = () => `<p class="hint">${A.source === "local" ? "Dados do servidor local (este computador, acesso total)." : A.source === "supabase" ? "Dados do Supabase (produção)." : "Dados de exemplo (demonstração): nada aqui é real."}</p>`;
  const csv = (rows, cols) => { const q = (v) => { let s = v == null ? "" : String(v); if (/^[=+\-@]/.test(s)) s = "'" + s; return /[";\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; }; return "﻿" + [cols.map((c) => q(c[0])).join(";"), ...rows.map((r) => cols.map((c) => q(typeof c[1] === "function" ? c[1](r) : r[c[1]])).join(";"))].join("\n"); };
  const dl = (name, content, type) => CF.download(name, content, type);
  // endereço público do app (para os links que vão para o cliente). Rodando local, aponta para a produção; dá para trocar em Prospecção.
  const APP_URL = () => { try { const v = localStorage.getItem("cf.admin.appurl"); if (v) return v.replace(/\/?$/, "/"); } catch (e) {}
    return /^(localhost|127\.0\.0\.1)$/.test(location.hostname) || location.protocol === "file:" ? "https://seu-cliente-fiel.vercel.app/app/" : location.origin + location.pathname.replace(/admin\/.*$/, ""); };
  const pageUrl = (slug) => `${APP_URL()}c/?s=${encodeURIComponent(slug)}`;
  const claimUrl = (tok) => `${APP_URL()}?ativar=${encodeURIComponent(tok)}`;
  const claimMsg = (nome, slug, tok) => `Olá! Tudo bem? Vi que o ${nome} é muito bem avaliado no Google e preparei, sem custo, uma página com cartão fidelidade digital para os seus clientes juntarem carimbos pelo celular: ${pageUrl(slug)}\n\nSe gostar, é só ativar (leva 1 minuto e o teste é grátis): ${claimUrl(tok)}`;
  const wa = (phone, text) => `https://wa.me/${String(phone || "").replace(/\D/g, "")}?text=${encodeURIComponent(text)}`;
  const copyBtn = (val, label = "Copiar") => `<button class="btn sm" type="button" data-copy="${esc(val)}">${I("copy", "sm")}${label}</button>`;
  document.addEventListener("click", async (e) => { const b = e.target.closest("[data-copy]"); if (!b) return; try { await (CF.copy ? CF.copy(b.dataset.copy) : navigator.clipboard.writeText(b.dataset.copy)); CF.toast("Copiado."); } catch (x) { CF.toast("Não foi possível copiar.", "err"); } });
  const strongPw = () => { const a = "abcdefghjkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789", r = new Uint32Array(12); crypto.getRandomValues(r); return Array.from(r, (x) => a[x % a.length]).join("").replace(/(.{4})(.{4})(.{4})/, "$1-$2-$3"); };
  // link de ativação novo (o anterior para de valer) + mensagem pronta
  const claimModal = async (biz) => {
    let r; try { r = await A.api("claim-link", {}, { id: biz.id, days: 60 }); } catch (e) { return CF.toast(e.message, "err"); }
    const msg = claimMsg(biz.name, biz.slug, r.token), ph = biz.prospect && biz.prospect.whatsapp;
    const ov = CF.modal({ title: `Link de ativação · ${esc(biz.name)}`, sub: `Vale até ${esc(when(r.expires_at))}. Ele só aparece agora: copie ou envie. Gerar outro invalida este.`, size: "lg",
      body: `<div class="stack-sm" style="gap:12px"><div class="field"><label>Página (em preparação)</label><div class="row" style="gap:8px"><input class="input" readonly value="${esc(pageUrl(biz.slug))}">${copyBtn(pageUrl(biz.slug))}</div></div>
        <div class="field"><label>Link de ativação</label><div class="row" style="gap:8px"><input class="input" readonly value="${esc(claimUrl(r.token))}">${copyBtn(claimUrl(r.token))}</div></div>
        <div class="field"><label>Mensagem</label><textarea class="input" rows="6" readonly>${esc(msg)}</textarea></div></div>`,
      foot: `${copyBtn(msg, "Copiar mensagem")}${ph ? `<a class="btn primary" href="${esc(wa(ph, msg))}" target="_blank" rel="noopener">${I("brand:whatsapp", "sm")}Enviar pelo WhatsApp</a>` : ""}<button class="btn" data-close>Fechar</button>` });
    return ov;
  };

  /* ---------- cobrança: formas de pagamento, links de pagamento (função billing/admin/*, migração 29) */
  const PROV = { stripe: { name: "Stripe", what: "Cartão de crédito · assinatura" }, asaas: { name: "Asaas", what: "Pix, boleto e cartão · assinatura ou pagamento único" },
    mercadopago: { name: "Mercado Pago", what: "Cartão (assinatura) · Pix, cartão e boleto (pagamento único)" }, pix: { name: "Pix manual", what: "Pix copia e cola · você confirma o recebimento" } };
  const PORDER = ["stripe", "asaas", "mercadopago", "pix"], METHOD = { card: "cartão", pix: "Pix", boleto: "boleto" };
  const LIVE = ["active", "trialing", "past_due"];
  const provPill = (bl) => (!bl || !bl.provider ? "" : `<span class="pill gray">${esc((PROV[bl.provider] || {}).name || bl.provider)}${bl.method ? " · " + esc(METHOD[bl.method] || bl.method) : ""}${bl.auto_renew === false && !bl.cancel_at_end ? " · avulso" : ""}</span>`);
  const linkPill = (l) => { const m = { open: ["amber", "em aberto"], paid: ["green", "pago"], canceled: ["gray", "cancelado"], expired: ["gray", "expirado"] }[l.status] || ["gray", l.status]; return `<span class="pill ${m[0]}">${esc(m[1])}</span>`; };
  const waPhone = (p) => { let d = String(p || "").replace(/\D/g, ""); if (d.length === 10 || d.length === 11) d = "55" + d; return d.length >= 12 ? d : ""; };
  const linkMsg = (l) => `Olá! Segue o link para pagar o plano Pro do ${CF.config.product} (${l.interval === "year" ? "anual" : "mensal"}, ${money(l.amount)}${l.kind === "subscription" ? ", renova sozinho" : ""}): ${l.url}`;
  const payInfo = async () => { const [st, cfg] = await Promise.all([A.api("pay-status").catch((e) => ({ error: e.message })), A.api("pay-config").catch(() => null)]); return { st, cfg }; };
  const linkResult = (biz, l, onClose) => {
    const msg = linkMsg(l), ph = waPhone(biz.phone || (biz.prospect && biz.prospect.whatsapp));
    CF.modal({ title: `Link de pagamento · ${esc(biz.name)}`, sub: `${esc((PROV[l.provider] || {}).name || l.provider)} · ${l.interval === "year" ? "anual" : "mensal"} · ${esc(money(l.amount))} · ${l.kind === "subscription" ? "assinatura (renova sozinha)" : "pagamento único (1 período)"}`, size: "lg", onClose,
      body: `<div class="stack-sm" style="gap:12px"><div class="field"><label>Link</label><div class="row" style="gap:8px"><input class="input" readonly value="${esc(l.url)}" id="lr-url">${copyBtn(l.url)}</div></div>
        <div class="field"><label>Mensagem</label><textarea class="input" rows="4" readonly>${esc(msg)}</textarea></div>
        <p class="hint">${l.provider === "pix" ? "Quando o Pix cair na sua conta, volte em Pagamentos e clique em “Confirmar recebimento”: o Pro liga por 1 período, somado ao que ainda falta." : "Quando o pagamento for confirmado, o Pro liga sozinho. Se o cliente pagava por outro meio, a assinatura anterior é cancelada para não cobrar duas vezes."}</p></div>`,
      foot: `${copyBtn(msg, "Copiar mensagem")}<a class="btn" href="${esc(l.url)}" target="_blank" rel="noopener">${I("external", "sm")}Abrir</a><a class="btn primary" href="${esc(ph ? wa(ph, msg) : "https://wa.me/?text=" + encodeURIComponent(msg))}" target="_blank" rel="noopener">${I("brand:whatsapp", "sm")}Enviar pelo WhatsApp</a><button class="btn" data-close>Fechar</button>` });
  };
  // gerar link: com biz (aba do negócio) ou escolhendo o negócio (lista em Pagamentos)
  const linkModal = async ({ biz, list, onDone }) => {
    const { st, cfg } = await payInfo();
    const av = (st && st.providers) || {}, prices = (cfg && cfg.prices) || (st && st.prices) || { month: PRICE().pro, year: (PRICE().proYear || PRICE().pro * 12) };
    const first = [(cfg && cfg.provider) || "stripe", ...PORDER].find((p) => av[p]) || "";
    const ov = CF.modal({ title: biz ? `Gerar link de pagamento · ${esc(biz.name)}` : "Gerar link de pagamento", sub: "Para o cliente pagar (ou trocar a forma de pagamento). O link vai pronto para copiar ou mandar no WhatsApp.", size: "lg",
      body: `<form class="form-grid" id="pl-f">${biz ? "" : `<div class="field wide"><label for="pl-biz">Negócio</label><select class="select" id="pl-biz" required><option value="">Escolha…</option>${(list || []).map((b) => `<option value="${esc(b.id)}">${esc(b.name)}${b.owner_email ? " · " + esc(b.owner_email) : ""}</option>`).join("")}</select></div>`}
        <div class="field wide"><label for="pl-pv">Forma de pagamento</label><select class="select" id="pl-pv">${PORDER.map((p) => `<option value="${p}" ${p === first ? "selected" : ""} ${av[p] ? "" : "disabled"}>${esc(PROV[p].name)} — ${esc(PROV[p].what)}${av[p] ? "" : " (não configurado)"}</option>`).join("")}</select></div>
        <div class="field"><label for="pl-kind">Tipo</label><select class="select" id="pl-kind"></select></div>
        <div class="field" id="pl-mf"><label for="pl-m">Meio</label><select class="select" id="pl-m"></select></div>
        <div class="field"><label for="pl-iv">Periodicidade</label><select class="select" id="pl-iv"><option value="month">Mensal</option><option value="year">Anual</option></select></div>
        <div class="field"><label for="pl-amt">Valor (R$)</label><input class="input" id="pl-amt" type="number" min="1" max="100000" step="0.01" value="${esc(String(prices.month))}"></div>
        <div class="field wide"><label for="pl-note">Observação (só aqui no painel)</label><input class="input" id="pl-note" maxlength="300" placeholder="Ex.: cliente pediu para trocar o cartão por Pix"></div>
        <p class="hint wide" id="pl-hint" style="grid-column:1/-1"></p>${st && st.error ? `<p class="wide small" style="grid-column:1/-1;color:var(--err-700)">${esc(st.error)}</p>` : ""}</form>`,
      foot: `<button class="btn" data-close>Cancelar</button><button class="btn primary" id="pl-go" ${first ? "" : "disabled"}>${I("link", "sm")}Gerar link</button>` });
    const g = (s) => ov.querySelector(s); let touched = false;
    const sync = () => { const pv = g("#pl-pv").value, kind0 = g("#pl-kind").value;
      const kinds = pv === "stripe" ? [["subscription", "Assinatura"]] : pv === "pix" ? [["one_time", "Pagamento único"]] : [["subscription", "Assinatura"], ["one_time", "Pagamento único"]];
      g("#pl-kind").innerHTML = kinds.map(([v, t]) => `<option value="${v}" ${v === kind0 ? "selected" : ""}>${t}</option>`).join(""); const kind = g("#pl-kind").value;
      const ms = pv === "asaas" || (pv === "mercadopago" && kind === "one_time") ? [["", "Cliente escolhe"], ["pix", "Só Pix"], ["boleto", "Só boleto"], ["card", "Só cartão"]] : null;
      const m0 = g("#pl-m").value; g("#pl-mf").style.display = ms ? "" : "none"; g("#pl-m").innerHTML = (ms || [["", ""]]).map(([v, t]) => `<option value="${v}" ${v === m0 ? "selected" : ""}>${t}</option>`).join("");
      if (!touched) g("#pl-amt").value = String(prices[g("#pl-iv").value] || prices.month);
      g("#pl-hint").textContent = pv === "pix" ? "Pagamento único: gera uma página com o QR code e o Pix copia e cola. Você confirma o recebimento em Pagamentos." : pv === "stripe" ? "Página segura da Stripe. O cartão fica salvo e a cobrança se renova sozinha." : kind === "subscription" ? `Assinatura no ${PROV[pv].name}${pv === "mercadopago" ? " (só cartão)" : ""}: renova e cobra sozinha a cada período.${pv === "asaas" && !g("#pl-m").value ? " O cliente escolhe Pix, boleto ou cartão na página do Asaas." : ""}` : `Pagamento único: cobra só este período no ${PROV[pv].name}. Para renovar, gere outro link.`; };
    ["#pl-pv", "#pl-kind", "#pl-iv", "#pl-m"].forEach((s) => g(s).addEventListener("change", sync)); g("#pl-amt").addEventListener("input", () => { touched = true; }); sync();
    g("#pl-go").addEventListener("click", async () => {
      const bid = biz ? biz.id : g("#pl-biz").value; if (!bid) return CF.toast("Escolha o negócio.", "err");
      const amount = Math.round(+g("#pl-amt").value * 100) / 100; if (!(amount >= 1)) return CF.toast("Valor inválido.", "err");
      const bt = g("#pl-go"); bt.disabled = true; bt.innerHTML = `<span class="spinner sm"></span>Gerando…`;
      try { const r = await A.api("pay-link", {}, { business: bid, provider: g("#pl-pv").value, kind: g("#pl-kind").value, method: g("#pl-m").value || null, interval: g("#pl-iv").value, amount, note: g("#pl-note").value.trim() || null });
        ov.close(); const b2 = biz || (list || []).find((x) => x.id === bid) || { id: bid, name: "" }; linkResult(b2, r.item); if (onDone) onDone(r.item); }
      catch (e) { bt.disabled = false; bt.innerHTML = `${I("link", "sm")}Gerar link`; CF.toast(e.message, "err"); }
    });
  };
  // link rápido: 1 clique gera o link do Pro (meio padrão, valor da tabela de preços), copia e abre a janela com a mensagem pronta
  const quickLink = async (biz, interval, btn) => {
    const old = btn && btn.innerHTML; if (btn) { btn.disabled = true; btn.innerHTML = `<span class="spinner sm"></span>Gerando…`; }
    try {
      const { st, cfg } = await payInfo(), av = (st && st.providers) || {}, prices = (cfg && cfg.prices) || (st && st.prices) || { month: PRICE().pro, year: PRICE().proYear || PRICE().pro * 12 };
      const pv = [(cfg && cfg.provider) || "stripe", ...PORDER].find((p) => av[p]); if (!pv) throw new Error((st && st.error) || "Nenhuma forma de pagamento está ligada. Veja Pagamentos → Formas de pagamento.");
      const amount = Number(prices[interval]) || Number(prices.month);
      const r = await A.api("pay-link", {}, { business: biz.id, provider: pv, kind: pv === "pix" ? "one_time" : "subscription", method: null, interval, amount, note: null });
      try { await (CF.copy ? CF.copy(r.item.url) : navigator.clipboard.writeText(r.item.url)); CF.toast("Link copiado. Cole no WhatsApp."); } catch (_) { /* a janela abaixo tem o botão Copiar */ }
      linkResult(biz, r.item);
    } catch (e) { CF.toast(e.message, "err"); } finally { if (btn) { btn.disabled = false; btn.innerHTML = old; } }
  };
  // lista de links (Pagamentos e aba do negócio) + ações: copiar, abrir, confirmar Pix, cancelar
  const linksHtml = (links, showBiz) => !links.length ? `<p class="muted">Nenhum link de pagamento.</p>` : `<div class="table-wrap"><div class="table-scroll"><table class="t"><thead><tr>${showBiz ? "<th>Negócio</th>" : ""}<th>Forma</th><th>Valor</th><th>Situação</th><th>Criado</th><th></th></tr></thead><tbody>
    ${links.map((l) => `<tr>${showBiz ? `<td><a href="#/businesses/${esc(l.business_id)}"><b>${esc(l.business || "")}</b></a></td>` : ""}<td>${esc((PROV[l.provider] || {}).name || l.provider)}<br><small class="muted">${l.kind === "subscription" ? "assinatura" : "pagamento único"}${l.method ? " · " + esc(METHOD[l.method] || l.method) : ""}${l.origin === "owner" ? " · pelo lojista" : ""}</small></td>
      <td><b>${esc(money(l.amount))}</b><br><small class="muted">${l.interval === "year" ? "anual" : "mensal"}</small></td><td>${linkPill(l)}${l.paid_at ? `<br><small class="muted">${esc(when(l.paid_at, true))}</small>` : ""}</td>
      <td><small>${esc(when(l.created_at, true))}${l.created_by ? "<br>" + esc(l.created_by) : ""}</small>${l.note ? `<br><small class="muted">${esc(l.note)}</small>` : ""}</td>
      <td><div class="row wrap" style="gap:6px;justify-content:flex-end">${l.url && l.status === "open" ? `${copyBtn(l.url, "Copiar")}<a class="btn sm ghost" href="${esc(l.url)}" target="_blank" rel="noopener" aria-label="Abrir o link">${I("external", "sm")}</a>` : ""}
        ${l.provider === "pix" && l.status === "open" ? `<button class="btn sm primary" type="button" data-lk="paid" data-id="${esc(l.id)}">${I("check", "sm")}Confirmar recebimento</button>` : ""}
        ${l.status === "open" ? `<button class="btn sm" type="button" data-lk="cancel" data-id="${esc(l.id)}">Cancelar</button>` : ""}</div></td></tr>`).join("")}</tbody></table></div></div>`;
  const bindLinks = (el, links, refresh) => el.addEventListener("click", (e) => {
    const b = e.target.closest("[data-lk]"); if (!b || !el.contains(b)) return; const l = links().find((x) => x.id === b.dataset.id); if (!l) return;
    if (b.dataset.lk === "paid") return CF.confirm({ title: "Confirmar o recebimento do Pix?", text: `${esc(l.business || "")}: ${esc(money(l.amount))} (${l.interval === "year" ? "anual" : "mensal"}). Confira no extrato do banco antes. O Pro liga por 1 período, somado ao que ainda falta.`, ok: "Confirmar recebimento",
      async onOk() { try { const r = await A.api("pay-mark-paid", {}, { link: l.id }); CF.toast(r && r.already ? "Este link já estava pago." : `Pagamento confirmado. Pro até ${when(r && r.period_end)}.`); refresh(); CF.adminRefreshTop(); } catch (x) { CF.toast(x.message, "err"); } } });
    if (b.dataset.lk === "cancel") return CF.confirm({ title: "Cancelar este link?", text: "Ele deixa de aceitar pagamento (também no provedor).", ok: "Cancelar link", danger: true,
      async onOk() { try { const r = await A.api("pay-cancel-link", {}, { link: l.id }); CF.toast(r && r.provider_ok === false ? "Link cancelado aqui. Confira no Mercado Pago se ele saiu do ar." : "Link cancelado."); refresh(); } catch (x) { CF.toast(x.message, "err"); } } });
  });

  /* ============================================================ shell */
  const NAV = [["dash", "Visão geral", "home", "/"], ["pay", "Pagamentos", "card", "/payments"], ["biz", "Negócios", "users", "/businesses"], ["new", "Criar / importar", "plus", "/create"], ["pros", "Prospecção", "sparkles", "/prospects"], ["visit", "Roteiro de visitas", "rocket", "/visitas"], ["exp", "Exportar", "download", "/export"], ["forja", "Chatbots (Forja)", "zap", "/forja"], ["keys", "Chaves e consumo", "key", "/keys"], ["audit", "Auditoria", "clipboard", "/audit"]];
  const srcLabel = () => (A.source === "local" ? "servidor local" : A.source === "supabase" ? "produção" : "demonstração");
  const shell = (active) => `<div class="app">
    <aside class="sidebar" id="sidebar"><a class="brand adm-logo" href="#/" aria-label="${esc(CF.config.product)} · Painel da plataforma"><img src="../assets/img/seucliente-logo.svg" alt="${esc(CF.config.product)}"><small>Painel da plataforma</small></a>
      <nav aria-label="Principal"><div class="nav-group open"><div>${NAV.map(([id, label, ic, href]) => `<a class="nav-item ${id === active ? "active" : ""}" href="#${href}" ${id === active ? 'aria-current="page"' : ""}>${I(ic)}<span>${label}</span></a>`).join("")}</div></div></nav>
      <div class="sidebar-foot"><span class="src ${A.source === "demo" || !A.source ? "demo" : ""}" id="src"><i></i>${srcLabel()}</span><a href="../" class="small">${I("arrow-left", "xs")} Voltar ao painel do lojista</a><span>${A.user ? esc(A.user.email) : "Demonstração"}</span>${A.user ? `<button class="link-btn" type="button" id="logout">Sair</button>` : ""}</div></aside>
    <div class="scrim" data-act="sb-close"></div>
    <div class="main"><header class="topbar adm-top"><button class="icon-btn" id="sb-toggle" aria-label="Alternar menu lateral">${I("menu")}</button>
      <div class="adm-stats" id="adm-stats" role="group" aria-label="Resumo da plataforma">${topStatsHtml(topCache.s)}</div></header>
      <main id="view" tabindex="-1"></main></div></div>`;

  /* ---------- barra do topo: só os números da plataforma, com ícones de linha (clicáveis), em 2 grupos:
     à esquerda os negócios (lojas, novas, teste, prospecção, clientes) e à direita o dinheiro (Pro, inadimplentes, cancelando, receita) */
  const TIP = {   // desenhos em linha (mesmo traço do CF.icon) que o conjunto do painel não tem
    store: '<path d="m2 7 4.41-4.41A2 2 0 0 1 7.83 2h8.34a2 2 0 0 1 1.42.59L22 7"/><path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8"/><path d="M15 22v-4a2 2 0 0 0-2-2h-2a2 2 0 0 0-2 2v4"/><path d="M2 7h20"/><path d="M22 7v3a2 2 0 0 1-2 2 2.7 2.7 0 0 1-1.59-.63.7.7 0 0 0-.82 0A2.7 2.7 0 0 1 16 12a2.7 2.7 0 0 1-1.59-.63.7.7 0 0 0-.82 0A2.7 2.7 0 0 1 12 12a2.7 2.7 0 0 1-1.59-.63.7.7 0 0 0-.82 0A2.7 2.7 0 0 1 8 12a2.7 2.7 0 0 1-1.59-.63.7.7 0 0 0-.82 0A2.7 2.7 0 0 1 4 12a2 2 0 0 1-2-2V7"/>',
    sprout: '<path d="M7 20h10"/><path d="M10 20c5.5-2.5.8-6.4 3-10"/><path d="M9.5 9.4c1.1.8 1.8 2.2 2.3 3.7-2 .4-3.5.4-4.8-.3-1.2-.6-2.3-1.9-3-4.2 2.8-.5 4.4 0 5.5.8z"/><path d="M14.1 6a7 7 0 0 0-1.1 4c1.9-.1 3.3-.6 4.3-1.4 1-1 1.6-2.3 1.7-4.6-2.7.1-4 1-4.9 2z"/>',
    timer: '<line x1="10" x2="14" y1="2" y2="2"/><line x1="12" x2="15" y1="14" y2="11"/><circle cx="12" cy="14" r="8"/>',
    rocket: '<path d="M4.5 16.5c-1.5 1.26-2 5-2 5s3.74-.5 5-2c.71-.84.7-2.13-.09-2.91a2.18 2.18 0 0 0-2.91-.09z"/><path d="m12 15-3-3a22 22 0 0 1 2-3.95A12.88 12.88 0 0 1 22 2c0 2.72-.78 7.5-6 11a22.35 22.35 0 0 1-4 2z"/><path d="M9 12H4s.55-3.03 2-4c1.62-1.08 5 0 5 0"/><path d="M12 15v5s3.03-.55 4-2c1.08-1.62 0-5 0-5"/>',
    "calendar-x": '<rect width="18" height="18" x="3" y="4" rx="2"/><path d="M16 2v4"/><path d="M8 2v4"/><path d="M3 10h18"/><path d="m14 14-4 4"/><path d="m10 14 4 4"/>',
    money: '<circle cx="12" cy="12" r="10"/><path d="M16 8h-6a2 2 0 1 0 0 4h4a2 2 0 1 1 0 4H8"/><path d="M12 18V6"/>',
  };
  const TI = (name) => (TIP[name] ? `<svg class="ic ts-ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${TIP[name]}</svg>` : I(name, "ts-ic"));
  const topCache = { s: null, at: 0 };
  function topStatsHtml(s) {
    const it = (href, ic, n, label, cls = "") => `<a class="ts-it ${cls}" href="#${href}" title="${esc(label)}" aria-label="${esc(label)}: ${esc(String(n))}">${TI(ic)}<b>${s ? esc(String(n)) : "…"}</b><small>${esc(label.split(" (")[0])}</small></a>`;
    const v = s || {};
    return `<div class="top-stats adm-ts adm-ts-l" role="group" aria-label="Negócios">
      ${it("/businesses", "store", v.businesses ?? 0, "Lojas")}
      ${it("/businesses", "sprout", v.new_30d ?? 0, "Novas (30 dias)")}
      ${it("/businesses", "timer", v.trial ?? 0, "Teste (em teste grátis)")}
      ${it("/prospects", "rocket", v.prospects_preview ?? 0, "Prospecção (em prospecção)")}
      ${it("/businesses", "users", Number(v.customers || 0).toLocaleString("pt-BR"), "Clientes (clientes com cartão)")}</div>
      <div class="top-stats adm-ts adm-ts-r" role="group" aria-label="Assinaturas e receita">
      ${it("/payments?f=active", "crown", v.sub_active ?? 0, "Assinantes (assinantes do plano Pro)")}
      ${it("/payments?f=past_due", "warn", v.sub_past_due ?? 0, "Inadimplentes", (v.sub_past_due || 0) > 0 ? "ts-bad" : "")}
      ${it("/payments?f=canceling", "calendar-x", v.sub_canceling ?? 0, "Cancelando")}
      ${it("/payments", "money", v.mrr != null ? money(v.mrr) : "R$ 0", "Receita/mês")}</div>`;
  }
  async function refreshTop(force) {
    const box = $("#adm-stats"); if (!box) return;
    if (!force && topCache.s && Date.now() - topCache.at < 60e3) { box.innerHTML = topStatsHtml(topCache.s); return; }
    try { const [s, pay] = await Promise.all([A.api("stats"), A.api("payments")]);
      s.mrr = (pay.items || []).reduce((a, b) => a + monthlyOf(b.billing), 0);
      topCache.s = s; topCache.at = Date.now(); const b2 = $("#adm-stats"); if (b2) b2.innerHTML = topStatsHtml(s); } catch (e) {}
  }

  const routes = [];
  const route = (pattern, handler) => { const keys = []; routes.push({ re: new RegExp("^" + pattern.replace(/:[a-z]+/gi, (m) => { keys.push(m.slice(1)); return "([^/]+)"; }) + "/?$"), keys, handler }); };
  const go = (p) => { location.hash = "#" + p; };
  let cleanup = null;
  async function render() {
    const path = decodeURIComponent((location.hash || "#/").slice(1).split("?")[0] || "/");
    let m = null, params = {}; for (const r of routes) { const x = r.re.exec(path); if (x) { m = r; r.keys.forEach((k, i) => (params[k] = x[i + 1])); break; } }
    try { cleanup && cleanup(); } catch (e) {} cleanup = null;
    const page = m ? m.handler(params) : { title: "Página não encontrada", nav: "", html: `<p class="muted">O endereço <code>${esc(path)}</code> não existe.</p>` };
    document.title = `${page.title} · Plataforma — ${CF.config.product}`;
    $("#root").innerHTML = shell(page.nav);
    $("#view").innerHTML = `<div class="page-head"><div class="left">${page.back ? `<a class="icon-btn back-btn" href="#${page.back}" aria-label="Voltar">${I("arrow-left")}</a>` : ""}<div><h1>${page.title}</h1>${page.sub ? `<p class="sub">${page.sub}</p>` : ""}</div></div>${page.actions ? `<div><div class="actions">${page.actions}</div></div>` : ""}</div>${page.html || ""}`;
    $("#sb-toggle").addEventListener("click", () => document.body.classList.toggle("sb-open"));
    $("#root").addEventListener("click", (e) => { if (e.target.closest("[data-act='sb-close']")) document.body.classList.remove("sb-open"); });
    const lo = $("#logout"); if (lo) lo.addEventListener("click", async () => { await A.logout(); location.reload(); });
    refreshTop();
    if (page.mount) cleanup = (await page.mount($("#view"))) || null;
    const src = $("#src"); if (src) { src.className = "src " + (A.source === "demo" ? "demo" : ""); src.innerHTML = `<i></i>${srcLabel()}`; }
  }
  CF.adminRefreshTop = () => refreshTop(true);   // telas que mudam plano/negócios chamam para atualizar a barra
  window.addEventListener("hashchange", () => { CF.closeLayers(); render(); window.scrollTo(0, 0); });

  /* ============================================================ Visão geral */
  route("/", () => ({ title: "Visão geral", sub: "Tudo o que acontece na plataforma: negócios, assinaturas e uso.", nav: "dash",
    html: `<div class="stack"><div class="kpis" id="kpis">${Array.from({ length: 8 }, () => `<div class="kpi"><div class="k">…</div><div class="v">…</div></div>`).join("")}</div>
      <div class="grid g2" style="gap:16px"><section class="card"><div class="card-h"><h2>Assinaturas que precisam de atenção</h2><p>Pagamento atrasado ou cancelamento marcado.</p></div><div class="card-b" id="att"><p class="muted">Carregando…</p></div></section>
      <section class="card"><div class="card-h"><h2>Negócios recentes</h2><p>Últimos cadastros.</p></div><div class="card-b" id="recent"><p class="muted">Carregando…</p></div></section></div>${srcNote()}</div>`,
    async mount(v) {
      try {
        const [s, pay] = await Promise.all([A.api("stats"), A.api("payments")]);
        const mrr = (pay.items || []).reduce((a, b) => a + monthlyOf(b.billing), 0);
        const kpi = (k, val, d, cls = "") => `<div class="kpi ${cls}"><div class="k">${k}</div><div class="v">${val}</div>${d ? `<div class="d">${d}</div>` : ""}</div>`;
        $("#kpis", v).innerHTML = kpi("Receita mensal recorrente", money(mrr), `${s.sub_month || 0} mensais · ${s.sub_year || 0} anuais`, "money") + kpi("Negócios", s.businesses, `${s.new_30d || 0} novos em 30 dias`) + kpi("Ativos em 30 dias", s.active_30d, "deram carimbo") + kpi("Assinaturas Pro", s.sub_active, `${s.paid || 0} com plano pago`) + kpi("Em teste grátis", s.trial, "ainda no Free") + kpi("Pagamento atrasado", s.sub_past_due, "", s.sub_past_due ? "money" : "") + kpi("Clientes com cartão", Number(s.customers || 0).toLocaleString("pt-BR")) + kpi("Carimbos em 30 dias", Number(s.stamps_30d || 0).toLocaleString("pt-BR"), `${s.redeemed_30d || 0} recompensas`);
        const att = (pay.items || []).filter((b) => b.billing && (b.billing.status === "past_due" || (b.billing.cancel_at_end && ["active", "trialing"].includes(b.billing.status))));
        $("#att", v).innerHTML = att.length ? att.map((b) => `<div class="list-row"><div style="flex:1"><b>${esc(b.name)}</b><br><small class="muted">${esc(b.owner_email || "")}</small></div>${subPill(b.billing)}<a class="btn sm" href="#/businesses/${esc(b.id)}">Abrir</a></div>`).join("") : `<p class="muted">Nada pendente. 🎉</p>`;
        $("#recent", v).innerHTML = (pay.items || []).slice(0, 6).map((b) => `<div class="list-row"><div style="flex:1"><b>${esc(b.name)}</b><br><small class="muted">${esc(when(b.created_at))} · ${b.customers} clientes</small></div>${planPill(b)}<a class="btn sm" href="#/businesses/${esc(b.id)}">Abrir</a></div>`).join("") || `<p class="muted">Nenhum negócio ainda.</p>`;
      } catch (e) { $("#kpis", v).innerHTML = err(e.message); }
    } }));

  /* ============================================================ Pagamentos */
  route("/payments", () => ({ title: "Pagamentos", sub: "Formas de pagamento, assinaturas por negócio e links de pagamento para mandar ao cliente.", nav: "pay",
    actions: `<button class="btn primary" id="pay-new">${I("link", "sm")}Gerar link de pagamento</button><button class="btn" id="pay-csv">${I("download", "sm")}Exportar CSV</button>`,
    html: `<div class="stack"><section class="card" id="pv-card"><div class="card-h"><h2>Formas de pagamento</h2><p>O provedor padrão é o que o lojista usa em Faturamento. Para um cliente que pediu outro meio, gere um link com a forma que ele quiser.</p></div><div class="card-b" id="pv-body"><p class="muted">Carregando…</p></div></section>
      <section class="card"><div class="card-h row between wrap" style="gap:10px"><div><h2>Assinaturas</h2><p>Clique no negócio para trocar o plano, gerar um link ou ver o histórico.</p></div>
        <select class="select" id="pay-f" aria-label="Filtrar" style="max-width:240px"><option value="">Todas</option><option value="active">Ativas</option><option value="past_due">Pagamento atrasado</option><option value="canceling">Cancelando</option><option value="canceled">Canceladas</option><option value="none">Sem assinatura</option></select></div>
      <div class="card-b"><div id="pay-list"><p class="muted">Carregando…</p></div></div></section>
      <section class="card"><div class="card-h row between wrap" style="gap:10px"><div><h2>Links de pagamento</h2><p>Gerados aqui ou pelo lojista. No Pix manual, confirme quando o dinheiro cair.</p></div>
        <select class="select" id="lk-f" aria-label="Filtrar links" style="max-width:200px"><option value="open">Em aberto</option><option value="paid">Pagos</option><option value="">Todos</option></select></div>
      <div class="card-b"><div id="lk-list"><p class="muted">Carregando…</p></div>${srcNote()}</div></section></div>`,
    async mount(v) {
      let items = [], links = [];
      const draw = () => { const f = $("#pay-f", v).value; const rows = items.filter((b) => { const bl = b.billing; if (!f) return true; if (f === "none") return !bl || !bl.status; if (!bl) return false; if (f === "canceling") return bl.cancel_at_end && ["active", "trialing", "past_due"].includes(bl.status); if (f === "active") return ["active", "trialing"].includes(bl.status); return bl.status === f; });
        const tot = rows.reduce((a, b) => a + monthlyOf(b.billing), 0);
        $("#pay-list", v).innerHTML = `<p class="small muted" style="margin-bottom:10px">${rows.length} negócios · receita mensal recorrente ${money(tot)}</p><div class="table-wrap"><div class="table-scroll"><table class="t"><thead><tr><th>Negócio</th><th>Plano</th><th>Assinatura</th><th>Meio</th><th>Periodicidade</th><th>Valor/mês</th><th>Próxima cobrança</th><th>Clientes</th><th></th></tr></thead><tbody>
          ${rows.map((b) => `<tr><td><b>${esc(b.name)}</b><br><small class="muted">${esc(b.owner_email || b.slug)}</small></td><td>${planPill(b)}</td><td>${subPill(b.billing)}</td><td>${provPill(b.billing) || "—"}${b.links_open ? `<br><small class="muted">${esc(String(b.links_open))} link(s) em aberto</small>` : ""}</td><td>${b.billing && b.billing.interval ? (b.billing.interval === "year" ? "Anual" : "Mensal") : "—"}</td><td><b>${monthlyOf(b.billing) ? money(monthlyOf(b.billing)) : "—"}</b></td><td>${b.billing && b.billing.period_end ? `${esc(when(b.billing.period_end))}${b.billing.auto_renew === false && !b.billing.cancel_at_end ? `<br><small class="muted">vence (não renova)</small>` : ""}` : "—"}</td><td>${esc(String(b.customers || 0))}</td><td><div class="row" style="gap:6px;justify-content:flex-end;flex-wrap:nowrap"><button class="btn sm primary" type="button" data-qlink="month" data-id="${esc(b.id)}" title="Gera o link mensal do Pro e copia">${I("link", "sm")}Link mensal</button><button class="btn sm" type="button" data-qlink="year" data-id="${esc(b.id)}" title="Gera o link anual do Pro e copia">Link anual</button><a class="btn sm" href="#/businesses/${esc(b.id)}">Abrir</a></div></td></tr>`).join("")}</tbody></table></div></div>`; };
      const drawLinks = () => { const f = $("#lk-f", v).value; $("#lk-list", v).innerHTML = linksHtml(links.filter((l) => !f || l.status === f), true); };
      const loadLinks = async () => { try { links = (await A.api("pay-links")).items || []; drawLinks(); } catch (e) { $("#lk-list", v).innerHTML = err(e.message); } };
      const loadAll = async () => { try { items = (await A.api("payments")).items || []; draw(); } catch (e) { $("#pay-list", v).innerHTML = err(e.message); } loadLinks(); };
      // formas de pagamento: provedor padrão, Pix (chave/nome/cidade), preços e carência. As chaves dos provedores ficam só nos segredos do Supabase.
      const drawProviders = async () => { const el = $("#pv-body", v); const { st, cfg } = await payInfo(); const c = cfg || { provider: "stripe", prices: { month: PRICE().pro, year: (PRICE().proYear || PRICE().pro * 12) }, pix: {}, grace_days: 5 };
        const av = (st && st.providers) || {}, mode = (st && st.mode) || {}, hooks = (st && st.webhooks) || {}, px = c.pix || {};
        el.innerHTML = `${st && st.error ? `<p class="small" style="color:var(--err-700);margin-bottom:10px">Não consegui saber quais provedores estão ligados: ${esc(st.error)}</p>` : ""}<div class="pv-grid" role="radiogroup" aria-label="Provedor padrão">${PORDER.map((p) => `<label class="pv-tile ${c.provider === p ? "on" : ""} ${av[p] || p === "pix" ? "" : "off"}">
            <span class="row between" style="gap:8px"><span class="row" style="gap:8px"><input type="radio" name="pv-def" value="${p}" ${c.provider === p ? "checked" : ""} ${av[p] || p === "pix" ? "" : "disabled"}><b>${esc(PROV[p].name)}</b></span>${p === "pix" ? (av.pix ? `<span class="pill green">pronto</span>` : `<span class="pill gray">falta a chave</span>`) : av[p] ? `<span class="pill green">ligado${mode[p] && mode[p] !== "produção" ? " · " + esc(mode[p]) : ""}</span>` : `<span class="pill gray">sem chaves</span>`}</span>
            <small class="muted">${esc(PROV[p].what)}</small>
            ${p === "pix" ? `<span class="pv-pix"><input class="input sm" id="px-key" maxlength="77" placeholder="Chave Pix (CNPJ, e-mail, celular +55… ou aleatória)" value="${esc(px.key || "")}" aria-label="Chave Pix"><span class="row" style="gap:6px"><input class="input sm" id="px-name" maxlength="25" placeholder="Nome do recebedor" value="${esc(px.name || "")}" aria-label="Nome do recebedor"><input class="input sm" id="px-city" maxlength="15" placeholder="Cidade" value="${esc(px.city || "")}" aria-label="Cidade do recebedor"></span></span>`
              : hooks[p] ? `<span class="pv-hook"><small class="muted">Webhook:</small> <code>${esc(hooks[p])}</code> ${copyBtn(hooks[p], "Copiar")}</span>` : ""}</label>`).join("")}</div>
          <div class="form-grid" style="margin-top:14px"><div class="field"><label for="pv-m">Preço mensal (R$)</label><input class="input" id="pv-m" type="number" min="1" step="0.01" value="${esc(String((c.prices || {}).month || PRICE().pro))}"></div><div class="field"><label for="pv-y">Preço anual (R$)</label><input class="input" id="pv-y" type="number" min="1" step="0.01" value="${esc(String((c.prices || {}).year || (PRICE().proYear || PRICE().pro * 12)))}"></div><div class="field"><label for="pv-g">Carência depois do vencimento (dias)</label><input class="input" id="pv-g" type="number" min="0" max="30" value="${esc(String(c.grace_days ?? 5))}"></div></div>
          <div class="row between wrap" style="gap:10px;margin-top:12px"><p class="hint" style="flex:1;min-width:240px;margin:0">As chaves da Stripe, do Asaas e do Mercado Pago ficam só no <code>.env.local</code> e vão para o Supabase com <code>python tools/enviar-segredos.py</code>, nunca aqui. Passo a passo em <code>docs/PAGAMENTOS.md</code>.</p><button class="btn primary" id="pv-save">${I("check", "sm")}Salvar formas de pagamento</button></div>`;
        el.querySelectorAll("[name=pv-def]").forEach((r) => r.addEventListener("change", () => el.querySelectorAll(".pv-tile").forEach((t) => t.classList.toggle("on", t.contains(r) && r.checked))));
        $("#pv-save", el).addEventListener("click", async () => { const pv = (el.querySelector("[name=pv-def]:checked") || {}).value || c.provider;
          const body = { provider: pv, prices: { month: +$("#pv-m", el).value, year: +$("#pv-y", el).value }, grace_days: +$("#pv-g", el).value, pix: { key: $("#px-key", el).value.trim(), name: $("#px-name", el).value.trim(), city: $("#px-city", el).value.trim() } };
          try { await A.api("pay-config-set", {}, { config: body }); CF.toast("Formas de pagamento salvas."); drawProviders(); } catch (e) { CF.toast(e.message, "err"); } }); };
      const qf = new URLSearchParams(location.hash.split("?")[1] || "").get("f"); if (qf && [...$("#pay-f", v).options].some((o) => o.value === qf)) $("#pay-f", v).value = qf;
      $("#pay-list", v).addEventListener("click", (e) => { const b = e.target.closest("[data-qlink]"); if (!b) return; const biz = items.find((x) => x.id === b.dataset.id); if (biz) quickLink(biz, b.dataset.qlink, b).then(loadAll); });
      drawProviders(); await loadAll();
      bindLinks($("#lk-list", v), () => links, loadAll);
      $("#pay-f", v).addEventListener("change", draw); $("#lk-f", v).addEventListener("change", drawLinks);
      $("#pay-new").addEventListener("click", () => linkModal({ list: items, onDone: loadAll }));
      $("#pay-csv").addEventListener("click", () => dl("assinaturas.csv", csv(items, [["negocio", "name"], ["slug", "slug"], ["email_dono", "owner_email"], ["plano", "plan"], ["teste", (r) => (r.trial ? "sim" : "não")], ["assinatura", (r) => (r.billing && r.billing.status) || ""], ["meio", (r) => (r.billing && r.billing.provider) || ""], ["forma", (r) => (r.billing && r.billing.method) || ""], ["renova", (r) => (r.billing ? (r.billing.auto_renew === false ? "não" : "sim") : "")], ["periodicidade", (r) => (r.billing && r.billing.interval) || ""], ["valor_mes", (r) => monthlyOf(r.billing)], ["proxima_cobranca", (r) => (r.billing && r.billing.period_end) || ""], ["cancela_no_fim", (r) => (r.billing && r.billing.cancel_at_end ? "sim" : "não")], ["stripe_customer", (r) => (r.billing && r.billing.customer_id) || ""], ["clientes", "customers"], ["criado_em", "created_at"]]), "text/csv"));
    } }));

  /* ============================================================ Negócios */
  // funções do painel do lojista (Aplicativo e telas → Painel do app): marque as que quer ver como colunas (migração admin_feature_usage)
  const FEATS = [["Página", [["capa", "Capa"], ["logo", "Logotipo"], ["fundo", "Fundo"], ["cartao", "Cartão"], ["icones", "Linha de ícones"], ["menus", "Menus"], ["catalogos", "Catálogos"], ["novidades", "Novidades"], ["whatsapp", "WhatsApp"], ["wifi", "Wi-Fi"], ["links", "Links"], ["mapa", "Mapa"]]],
    ["Engajamento", [["campanha", "Campanha"], ["aniversarios", "Aniversários"], ["pesquisa", "Pesquisa"], ["google", "Avaliações Google"], ["qr", "QR impresso"]]], ["Pro", [["pro", "Sem marca d’água"]]]];
  const FLIST = FEATS.flatMap(([, l]) => l), FTOTAL = FLIST.length, FKEY = "cf.admin.bzfeats";
  const fOn = (v) => (typeof v === "number" ? v > 0 : !!v);
  const fCell = (k, v) => { if (!fOn(v)) return `<td data-sort="0" class="muted" title="Não usa">—</td>`; const det = k === "cartao" ? `${v} carimbos` : typeof v === "number" ? String(v) : "";
    return `<td data-sort="${typeof v === "number" ? v : 1}" title="Usa"><span class="adm-fon">${I("check", "sm")}${det ? `<small>${esc(det)}</small>` : ""}</span></td>`; };
  const getF = () => { try { const v = JSON.parse(localStorage.getItem(FKEY) || "null"); if (Array.isArray(v)) return v; } catch (e) {} return ["total"]; };
  const setF = (v) => { try { localStorage.setItem(FKEY, JSON.stringify(v)); } catch (e) {} };
  route("/businesses", () => ({ title: "Negócios", sub: "Todos os estabelecimentos: plano, uso, ficha do Google, chatbot e as funções que cada lojista está usando.", nav: "biz",
    actions: `<a class="btn primary" href="#/create">${I("plus", "sm")}Criar estabelecimento</a>`,
    html: `<div class="stack"><section class="card"><div class="card-h row between wrap" style="gap:10px"><div><h2>Estabelecimentos</h2></div><div class="row" style="gap:8px"><select class="select" id="bz-plan" aria-label="Plano" style="max-width:150px"><option value="">Todos os planos</option><option value="free">Free</option><option value="pro">Pro</option></select><input class="input" id="bz-q" type="search" placeholder="Buscar por nome, slug ou e-mail" aria-label="Buscar" style="max-width:300px"></div></div>
      <div class="card-b"><details class="adm-feats" id="bz-fd"><summary>${I("grid", "sm")}Funções em uso na tabela <span class="muted" id="bz-fn"></span></summary><div class="adm-feats-b">
          <label class="check"><input type="checkbox" data-f="total"><span><b>Em uso (total)</b> · quantas das ${FTOTAL} funções o lojista usa</span></label>
          ${FEATS.map(([g, l]) => `<div class="adm-feats-g"><b>${g}</b>${l.map(([k, t]) => `<label class="check"><input type="checkbox" data-f="${k}"><span>${esc(t)}</span></label>`).join("")}</div>`).join("")}
          <div class="row wrap" style="gap:8px"><button class="btn sm" type="button" data-fall>Marcar todas</button><button class="btn sm ghost" type="button" data-fnone>Limpar</button></div>
          <p class="hint" style="margin:0">Mesmas regras do “Aplicativo e telas” do painel do lojista. Notificações não aparecem: o lojista liga no navegador dele e isso não fica no servidor.</p></div></details>
        <div id="bz-list"><p class="muted">Carregando…</p></div>${srcNote()}</div></section></div>`,
    async mount(v) {
      let items = [], fm = {};
      const draw = () => { const q = (CF.norm || ((s) => String(s).toLowerCase()))($("#bz-q", v).value || ""), pf = $("#bz-plan", v).value;
        const sel = getF(), tot = sel.includes("total"), cols = FLIST.filter(([k]) => sel.includes(k));
        $("#bz-fn", v).textContent = sel.length ? `(${sel.length} marcada${sel.length > 1 ? "s" : ""})` : "";
        v.querySelectorAll("[data-f]").forEach((c) => (c.checked = sel.includes(c.dataset.f)));
        const rows = items.filter((b) => (!q || (CF.norm || String)(`${b.name} ${b.slug} ${b.owner_email || ""}`).includes(q)) && (!pf || (pf === "free" ? b.plan === "free" : b.plan !== "free")));
        $("#bz-list", v).innerHTML = rows.length ? `<div class="table-wrap"><div class="table-scroll"><table class="t" data-tk="admin-negocios"><thead><tr><th>Negócio</th><th>Plano</th><th>Clientes</th><th>Carimbos 30 d</th><th>Visitantes 30 d</th><th>Google</th><th>Chatbot</th><th>Desde</th>${tot ? "<th>Em uso</th>" : ""}${cols.map(([, t]) => `<th>${esc(t)}</th>`).join("")}<th></th></tr></thead><tbody>
          ${rows.map((b) => { const f = fm[b.id] || {}, n = FLIST.filter(([k]) => fOn(f[k])).length;
            const extra = (tot ? `<td data-sort="${n}"><span class="adm-fbar" title="${n} de ${FTOTAL} funções em uso"><i style="width:${Math.round((n / FTOTAL) * 100)}%"></i></span><small>${n}/${FTOTAL}</small></td>` : "") + cols.map(([k]) => fCell(k, f[k])).join("");
            return `<tr>__CELLS__</tr>`.replace("__CELLS__", ROW(b, extra)); }).join("")}</tbody></table></div></div>` : `<p class="muted">Nenhum negócio encontrado.</p>`; };
      const ROW = (b, extra) => `<td><div class="row" style="gap:10px"><img src="${esc(b.logo_url || "../assets/img/logo-placeholder.png")}" alt="" width="28" height="28" style="border-radius:8px;object-fit:cover"><div><b>${esc(b.name)}</b><br><small class="muted">${esc(b.slug)}${b.owner_email ? " · " + esc(b.owner_email) : ""}</small></div></div></td><td>${planPill(b)}</td><td>${esc(String(b.customers || 0))}</td><td>${esc(String(b.stamps_30d || 0))}</td><td>${esc(String(b.visitors_30d || 0))}</td><td>${b.gmaps && b.gmaps.nome ? `★ ${esc(String(b.gmaps.nota || "—"))} · ${esc(String(b.gmaps.total_avaliacoes || 0))}` : `<span class="muted">—</span>`}</td><td>${forjaPill(b.forja)}</td><td>${esc(when(b.created_at))}</td>${extra}<td><div class="row" style="gap:6px;justify-content:flex-end;flex-wrap:nowrap"><button class="btn sm primary" type="button" data-qlink="month" data-id="${esc(b.id)}" title="Gera o link mensal do Pro e copia">${I("link", "sm")}Link mensal</button><button class="btn sm" type="button" data-qlink="year" data-id="${esc(b.id)}" title="Gera o link anual do Pro e copia">Link anual</button><a class="btn sm" href="#/businesses/${esc(b.id)}">Abrir</a></div></td>`;
      try { const [bz, fe] = await Promise.all([A.api("businesses"), A.api("features").catch(() => ({ items: [] }))]); items = bz.items || []; fm = Object.fromEntries((fe.items || []).map((x) => [x.id, x.f || {}])); draw(); } catch (e) { $("#bz-list", v).innerHTML = err(e.message); }
      $("#bz-list", v).addEventListener("click", (e) => { const b = e.target.closest("[data-qlink]"); if (!b) return; const biz = items.find((x) => x.id === b.dataset.id); if (biz) quickLink(biz, b.dataset.qlink, b); });
      $("#bz-q", v).addEventListener("input", CF.debounce(draw, 120)); $("#bz-plan", v).addEventListener("change", draw);
      $("#bz-fd", v).addEventListener("change", (e) => { const c = e.target.closest("[data-f]"); if (!c) return; const s2 = new Set(getF()); c.checked ? s2.add(c.dataset.f) : s2.delete(c.dataset.f); setF([...s2]); draw(); });
      $("#bz-fd", v).addEventListener("click", (e) => { if (e.target.closest("[data-fall]")) { setF(["total", ...FLIST.map(([k]) => k)]); draw(); } if (e.target.closest("[data-fnone]")) { setF([]); draw(); } });
      if (getF().length > 1) $("#bz-fd", v).open = true;
    } }));

  /* ============================================================ Negócio: detalhe com abas */
  const TABS = [["geral", "Geral e plano"], ["acesso", "Acesso"], ["card", "Cartão"], ["page", "Página e itens"], ["sug", "Sugestões"], ["cust", "Clientes"], ["nav", "Menu do painel"], ["forja", "Chatbot"], ["model", "Exportar / modelo"]];
  const ITEM_TYPES = [["menu", "Menu"], ["catalog", "Catálogo"], ["news", "Novidades"], ["link", "Link"], ["contact", "Contato"], ["social", "Rede social"], ["wifi", "Wi-Fi"], ["gmaps", "Google Maps"], ["testimonials", "Depoimentos"], ["hours", "Horário"]];
  route("/businesses/:id", ({ id }) => ({ title: "Negócio", nav: "biz", back: "/businesses", html: `<div class="stack" id="bz"><p class="muted">Carregando…</p></div>`,
    async mount(v) {
      let b, tab = (location.hash.split("?")[1] || "").replace(/^tab=/, "") || "geral", nav = [], items = [], pay = null, events = [];
      const root = $("#bz", v);
      const head = () => `<div class="row wrap" style="gap:12px;align-items:center"><img src="${esc(b.logo_url || "../assets/img/logo-placeholder.png")}" alt="" width="48" height="48" style="border-radius:12px;object-fit:cover"><div style="flex:1;min-width:0"><h2 style="font-size:20px">${esc(b.name)}</h2><small class="muted">${esc(b.slug)}${b.owner_email ? " · " + esc(b.owner_email) : ""} · desde ${esc(when(b.created_at))}</small></div>${planPill(b)}${pay ? subPill(pay.billing) : ""}<a class="btn sm" href="../c/?s=${encodeURIComponent(b.slug)}" target="_blank" rel="noopener">${I("external", "sm")}Página do cliente</a></div>
        <div class="stat-inline card" style="padding:16px 22px"><div><b>${esc(String(b.customers || 0))}</b><span>clientes</span></div><div><b>${esc(String(b.stamps_total || 0))}</b><span>carimbos</span></div><div><b>${esc(String(b.redeemed_total || 0))}</b><span>recompensas</span></div><div><b>${esc(String(b.visitors_30d || 0))}</b><span>visitantes 30 d</span></div><div><b>${esc(String(b.leads || 0))}</b><span>contatos Wi-Fi</span></div><div><b>${esc(String(b.staff || 0))}</b><span>funcionários</span></div></div>
        <div class="tabs" role="tablist">${TABS.map(([k, t]) => `<button type="button" role="tab" data-tab="${k}" class="${k === tab ? "on" : ""}" aria-selected="${k === tab}">${t}${k === "sug" && b.suggestions_open ? ` <span class="adm-sug-n" aria-label="${esc(String(b.suggestions_open))} em aberto">${esc(String(b.suggestions_open))}</span>` : ""}</button>`).join("")}</div><div id="tab"></div>${srcNote()}`;
      const paint = () => { root.innerHTML = head(); drawTab(); };
      const drawTab = () => { const el = $("#tab", root); root.querySelectorAll("[data-tab]").forEach((x) => { const on = x.dataset.tab === tab; x.classList.toggle("on", on); x.setAttribute("aria-selected", on); }); ({ geral, acesso, card, page, sug, cust, nav: navTab, forja, model })[tab](el); };
      const oldDb = () => err("O banco precisa da atualização (Atualizar banco (Supabase).bat): sem ela o painel não recebe os itens atuais da página, e salvar daqui apagaria a página.");

      /* ---------- Acesso: dono e equipe, trocar senha, links de redefinição/acesso; página em preparação → link de ativação */
      const acesso = async (el) => {
        el.innerHTML = `<p class="muted">Carregando…</p>`;
        let o; try { o = await A.api("owner", { id: b.id }); } catch (e) { el.innerHTML = err(e.message); return; }
        const u = o.owner || {}, preview = !!(o.prospect && o.prospect.status === "preview"), pre = preview && !!u.is_platform_account;   // pre: ainda na conta técnica
        const temp = /\.invalid$/i.test(u.email || "") || (preview && /@seuclientefiel\.com\.br$/i.test(u.email || ""));   // e-mail provisório da página em preparação (<slug>@seuclientefiel.com.br; antigas: .invalid): troque pelo real
        const line = (k, v) => `<div class="field"><label>${k}</label><div>${v}</div></div>`;
        const acts = (uid, who) => `<div class="row wrap" style="gap:8px;margin-top:12px" data-user="${esc(uid)}" data-who="${esc(who)}">
            <button class="btn primary sm" type="button" data-acc="set-password">${I("key", "sm")}Definir nova senha</button>
            <button class="btn sm" type="button" data-acc="recovery-link">${I("link", "sm")}Gerar link de redefinição</button>
            <button class="btn sm" type="button" data-acc="send-recovery">${I("send", "sm")}Enviar e-mail de redefinição</button>
            <button class="btn sm" type="button" data-acc="set-email">${I("mail", "sm")}Trocar e-mail</button>
            <button class="btn sm ghost" type="button" data-acc="magic-link">${I("external", "sm")}Gerar link de acesso direto</button></div><div class="acc-out" style="margin-top:10px"></div>`;
        const ownerCard = pre ? `<section class="card"><div class="card-h row between wrap" style="gap:10px"><div><h2>Página em preparação</h2><p>Criada para prospecção: ainda sem dono. Clientes não conseguem se cadastrar até o estabelecimento ativar.</p></div><span class="pill amber">em preparação</span></div>
            <div class="card-b stack-sm" style="gap:12px"><div class="form-grid">${line("Conta que guarda a página", esc(u.email || "—"))}${line("Origem", esc((o.prospect.source || "—") + (o.prospect.segmento ? " · " + o.prospect.segmento : "")))}${line("WhatsApp do estabelecimento", o.prospect.whatsapp ? esc(o.prospect.whatsapp) : "—")}${line("Nota no Google", o.prospect.rating ? `★ ${esc(String(o.prospect.rating))} · ${esc(String(o.prospect.reviews || 0))} avaliações` : "—")}</div>
              <div class="row wrap" style="gap:8px"><button class="btn primary" type="button" id="cl-new">${I("sparkles", "sm")}Gerar link de ativação</button><a class="btn" href="${esc(pageUrl(b.slug))}" target="_blank" rel="noopener">${I("external", "sm")}Ver a página</a></div>
              <p class="hint">O link vale 60 dias e mostra a página que o dono vai assumir. Gerar um novo invalida o anterior.</p></div></section>`
          : `${preview ? `<section class="card"><div class="card-h row between wrap" style="gap:10px"><div><h2>Página em prévia</h2><p>Já tem conta própria. Os clientes ainda não conseguem se cadastrar: ela é liberada quando o dono clica em “Ativar minha página” no painel dele, ou por você aqui.</p></div><span class="pill amber">em prévia</span></div>
              <div class="card-b"><div class="row wrap" style="gap:8px"><button class="btn primary" type="button" id="pv-activate">${I("check", "sm")}Ativar página agora</button><a class="btn" href="${esc(pageUrl(b.slug))}" target="_blank" rel="noopener">${I("external", "sm")}Ver a página</a></div>
              <p class="hint" style="margin-top:8px">Ativar começa o teste grátis de 21 dias do estabelecimento a partir de hoje.</p></div></section>` : ""}
            <section class="card"><div class="card-h row between wrap" style="gap:10px"><div><h2>Dono da conta</h2><p>Quem entra no painel deste negócio.</p></div>${u.is_admin ? `<span class="pill">superadmin</span>` : ""}${temp ? `<span class="pill amber">e-mail temporário</span>` : ""}</div>
            <div class="card-b">${temp ? `<p class="small" style="margin-bottom:10px">Este e-mail é temporário (não recebe mensagens). Use <b>Trocar e-mail</b> quando o dono passar o e-mail dele; a senha continua a mesma.</p>` : ""}<div class="form-grid">${line("E-mail", `<b>${esc(u.email || "—")}</b> ${u.email ? copyBtn(u.email) : ""}`)}${line("Nome", esc(u.name || "—"))}${line("Conta criada", esc(when(u.created_at, true)))}${line("Último acesso", esc(when(u.last_sign_in_at, true)))}${line("E-mail confirmado", u.email_confirmed_at ? `sim (${esc(when(u.email_confirmed_at))})` : `<span class="pill amber">não</span>`)}${line("Negócios desta conta", esc(String(u.businesses || 1)))}</div>
              ${u.banned_until && new Date(u.banned_until) > new Date() ? `<p class="small" style="color:var(--err-700);margin-top:8px">Conta bloqueada até ${esc(when(u.banned_until, true))}.</p>` : ""}
              ${u.id && !u.is_admin ? acts(u.id, u.email) : `<p class="hint" style="margin-top:10px">Superadmin: troque a senha pela própria conta.</p>`}</div></section>`;
        const staff = (o.staff || []);
        el.innerHTML = `<div class="stack" style="gap:16px">${ownerCard}
          <section class="card"><div class="card-h"><h2>Equipe</h2><p>Funcionários com acesso para dar carimbos.</p></div><div class="card-b">${staff.length ? staff.map((s) => `<div class="list-row" style="flex-wrap:wrap"><div style="flex:1;min-width:200px"><b>${esc(s.name)}</b><br><small class="muted">${esc(s.email)} · ${esc({ pending: "convite pendente", active: "ativo", revoked: "revogado" }[s.status] || s.status)} · último acesso ${esc(when(s.last_sign_in_at, true))}</small></div>${s.user_id ? `<div style="flex-basis:100%">${acts(s.user_id, s.email)}</div>` : `<small class="muted">ainda não criou a conta</small>`}</div>`).join("") : `<p class="muted">Nenhum funcionário.</p>`}</div></section>
          <p class="hint">Tudo o que você faz aqui fica na Auditoria. O e-mail de redefinição depende do SMTP do Supabase (Auth › SMTP); os links gerados você mesmo envia (WhatsApp, por exemplo).</p></div>`;
        const pa = $("#pv-activate", el); if (pa) pa.addEventListener("click", () => CF.confirm({ title: "Ativar a página agora?", text: "Os clientes passam a poder se cadastrar e o teste grátis de 21 dias começa hoje.", ok: "Ativar página",
          async onOk() { try { await A.api("activate-prospect", {}, { id: b.id }); CF.toast("Página ativada."); if (b.prospect) b.prospect.status = "claimed"; acesso(el); } catch (e) { CF.toast(e.message, "err"); } } }));
        const cn = $("#cl-new", el); if (cn) cn.addEventListener("click", () => CF.confirm({ title: "Gerar link de ativação?", text: "Se já existe um link, ele deixa de valer.", ok: "Gerar", onOk: () => claimModal(Object.assign({}, b, { prospect: o.prospect })) }));
        el.querySelectorAll("[data-acc]").forEach((btn) => btn.addEventListener("click", async () => {
          const box = btn.closest("[data-user]"), uid = box.dataset.user, who = box.dataset.who, out = box.nextElementSibling, act = btn.dataset.acc;
          if (act === "set-password") {
            const pw0 = strongPw();
            const ov = CF.modal({ title: "Definir nova senha", sub: `Para ${esc(who)}. A senha antiga deixa de valer na hora.`, body: `<div class="field"><label for="np-v">Nova senha (mín. 8)</label><div class="row" style="gap:8px"><input class="input" id="np-v" value="${esc(pw0)}" autocomplete="off" spellcheck="false"><button class="btn sm" type="button" id="np-g">${I("refresh", "sm")}Gerar outra</button></div><span class="hint">Envie ao cliente por um canal seguro e peça para trocar depois de entrar.</span></div>`,
              foot: `<button class="btn" data-close>Cancelar</button><button class="btn primary" id="np-ok">${I("check", "sm")}Salvar nova senha</button>` });
            ov.querySelector("#np-g").addEventListener("click", () => { ov.querySelector("#np-v").value = strongPw(); });
            ov.querySelector("#np-ok").addEventListener("click", async () => { const pw = ov.querySelector("#np-v").value.trim(); if (pw.length < 8) return CF.toast("A senha precisa ter pelo menos 8 caracteres.", "err");
              try { await A.api("set-password", {}, { user_id: uid, password: pw, business_id: b.id }); ov.close(); out.innerHTML = `<div class="alert" style="background:var(--ok-50,#ecfdf3);border-radius:10px;padding:10px 12px"><b>Senha trocada.</b> Nova senha: <code>${esc(pw)}</code> ${copyBtn(pw)}</div>`; CF.toast("Senha trocada."); } catch (e) { CF.toast(e.message, "err"); } });
            return;
          }
          if (act === "set-email") {
            const ov = CF.modal({ title: "Trocar e-mail de acesso", sub: `Hoje: ${esc(who)}. O novo e-mail já entra confirmado; a senha não muda.`, body: `<div class="field"><label for="ne-v">Novo e-mail</label><input class="input" id="ne-v" type="email" autocomplete="off" spellcheck="false" placeholder="dono@exemplo.com.br"></div>`,
              foot: `<button class="btn" data-close>Cancelar</button><button class="btn primary" id="ne-ok">${I("check", "sm")}Trocar e-mail</button>` });
            ov.querySelector("#ne-ok").addEventListener("click", async () => { const em = ov.querySelector("#ne-v").value.trim().toLowerCase(); if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(em)) return CF.toast("E-mail inválido.", "err");
              try { const r = await A.api("set-email", {}, { user_id: uid, email: em, business_id: b.id }); ov.close(); CF.toast(`E-mail trocado para ${r.email || em}.`); if (box.closest("section") && who === u.email) b.owner_email = r.email || em; acesso(el); } catch (e) { CF.toast(e.message, "err"); } });
            return;
          }
          if (act === "send-recovery") return CF.confirm({ title: "Enviar e-mail de redefinição?", text: `Vai para ${esc(who)}.`, ok: "Enviar", async onOk() { try { await A.api("send-recovery", {}, { user_id: uid, business_id: b.id }); out.innerHTML = `<p class="small">E-mail de redefinição enviado para <b>${esc(who)}</b>.</p>`; CF.toast("E-mail enviado."); } catch (e) { CF.toast(e.message, "err"); } } });
          btn.disabled = true;
          try { const r = await A.api(act, {}, { user_id: uid, business_id: b.id }); const txt = act === "recovery-link" ? `Para criar uma nova senha no ${CF.config.product}, abra: ${r.link}` : `Para entrar no ${CF.config.product}, abra: ${r.link}`;
            out.innerHTML = `<div class="field"><label>${act === "recovery-link" ? "Link de redefinição de senha (uso único)" : "Link de acesso direto (uso único)"}</label><div class="row wrap" style="gap:8px"><input class="input" readonly value="${esc(r.link)}" style="flex:1;min-width:220px">${copyBtn(r.link)}<a class="btn sm" href="https://wa.me/?text=${encodeURIComponent(txt)}" target="_blank" rel="noopener">${I("brand:whatsapp", "sm")}WhatsApp</a></div></div>`; }
          catch (e) { CF.toast(e.message, "err"); } finally { btn.disabled = false; }
        }));
      };

      const geral = (el) => { const bl = pay && pay.billing; const st = b.settings || {}; const w = st.welcome || {}, rc = st.receipts || {};
        el.innerHTML = `<div class="grid g2" style="gap:16px;align-items:start">
          <section class="card"><div class="card-h"><h2>Plano e cobrança</h2><p>Troca manual do plano. O provedor de pagamento sobrescreve quando a assinatura muda.</p></div><div class="card-b stack-sm" style="gap:12px">
            <div class="form-grid"><div class="field"><label for="pl-plan">Plano</label><select class="select" id="pl-plan">${["free", "pro"].map((p) => `<option value="${p}" ${(b.plan === "free" ? "free" : "pro") === p ? "selected" : ""}>${p === "free" ? "Free" : "Pro"}</option>`).join("")}</select></div>
              <div class="field"><label for="pl-trial">Teste grátis</label><select class="select" id="pl-trial"><option value="1" ${b.trial ? "selected" : ""}>Ligado</option><option value="0" ${b.trial ? "" : "selected"}>Desligado</option></select></div></div>
            <div class="row" style="justify-content:flex-end"><button class="btn primary" id="pl-save">${I("check", "sm")}Aplicar plano</button></div>
            <hr class="divider">${bl && bl.status ? `<div class="small stack-sm" style="gap:4px"><b>Assinatura</b><span>Situação: ${subPill(bl)}</span><span>Meio: ${provPill(bl) || `<span class="pill gray">Stripe</span>`}</span><span>Periodicidade: <b>${bl.interval === "year" ? "Anual" : bl.interval === "month" ? "Mensal" : "—"}</b> · Valor/mês: <b>${monthlyOf(bl) ? money(monthlyOf(bl)) : "—"}</b></span><span>${bl.auto_renew === false || bl.cancel_at_end ? "Válido até" : "Próxima cobrança"}: <b>${esc(when(bl.period_end))}</b></span>${bl.customer_id && (bl.provider || "stripe") === "stripe" ? `<span>Cliente Stripe: <a href="https://dashboard.stripe.com/customers/${esc(bl.customer_id)}" target="_blank" rel="noopener"><code>${esc(bl.customer_id)}</code> ${I("external", "xs")}</a></span>` : ""}
              ${events.length ? `<details><summary class="small">Histórico de eventos (${events.length})</summary><ul class="small muted" style="padding-left:16px;margin-top:6px">${events.map((e) => `<li>${esc(when(e.at, true))} — ${esc(e.type)}</li>`).join("")}</ul></details>` : ""}</div>` : `<p class="small muted">Sem assinatura.</p>`}
            <div class="row wrap" style="gap:8px"><button class="btn sm primary" type="button" id="pl-link">${I("link", "sm")}Gerar link de pagamento</button>${bl && LIVE.includes(bl.status) && !bl.cancel_at_end && bl.auto_renew !== false ? `<button class="btn sm" type="button" id="pl-stop">Cancelar renovação</button>` : ""}</div>
            <div id="pl-links"><p class="small muted">Carregando links…</p></div>
          </div></section>
          <section class="card"><div class="card-h"><h2>Dados do negócio</h2><p>O que aparece na página do cliente.</p></div><div class="card-b stack-sm" style="gap:12px">
            <div class="adm-logo-edit"><img id="g-logo" src="${esc(b.logo_url || "../assets/img/logo-placeholder.png")}" alt="Logo de ${esc(b.name)}" width="64" height="64"><div class="stack-sm" style="gap:6px;min-width:0"><b>Logo</b><small class="muted">PNG, JPG ou WebP. Fica num círculo na página do cliente (ajustamos para quadrado, 256 px).</small>
              <div class="row wrap" style="gap:8px"><input type="file" id="g-logo-f" accept="image/png,image/jpeg,image/webp" class="sr-only"><label class="btn sm" for="g-logo-f">${I("upload", "sm")}${b.logo_url ? "Trocar logo" : "Enviar logo"}</label>${b.logo_url ? `<button class="btn sm ghost" type="button" id="g-logo-rm">Remover</button>` : ""}</div></div></div>
            <form id="bz-form" class="form-grid">
            <div class="field"><label for="g-name">Nome</label><input class="input" id="g-name" value="${esc(b.name)}" maxlength="100"></div><div class="field"><label for="g-type">Tipo</label><input class="input" id="g-type" value="${esc(b.type || "")}" maxlength="40"></div>
            <div class="field wide"><label for="g-tag">Frase de apresentação</label><input class="input" id="g-tag" value="${esc(b.tagline || "")}" maxlength="140"></div><div class="field wide"><label for="g-addr">Endereço</label><input class="input" id="g-addr" value="${esc(b.address || "")}" maxlength="200"></div>
            <div class="field"><label for="g-color">Cor da página</label><input class="input" id="g-color" type="color" value="${esc(b.page_color || "#fef0c7")}"></div><div class="field"><label for="g-tz">Fuso horário</label><input class="input" id="g-tz" value="${esc(b.tz || "America/Sao_Paulo")}"></div><div class="field"><label for="g-cur">Moeda</label><select class="select" id="g-cur">${["BRL", "EUR", "USD"].map((c) => `<option ${c === (b.currency || "BRL") ? "selected" : ""}>${c}</option>`).join("")}</select></div>
            <div class="field"><label for="g-wel">Carimbo de boas-vindas</label><select class="select" id="g-wel"><option value="off" ${w.mode === "off" || !w.mode ? "selected" : ""}>Desligado</option><option value="auto" ${w.mode === "auto" ? "selected" : ""}>Automático</option><option value="approve" ${w.mode === "approve" ? "selected" : ""}>Com aprovação</option></select></div><div class="field"><label for="g-welq">Quantidade</label><input class="input" id="g-welq" type="number" min="1" max="5" value="${esc(String(w.qty || 1))}"></div>
            <div class="field"><label for="g-rc">Comprovante pelo WhatsApp</label><select class="select" id="g-rc"><option value="1" ${rc.on !== false ? "selected" : ""}>Ligado</option><option value="0" ${rc.on === false ? "selected" : ""}>Desligado</option></select></div><div class="field"><label for="g-rcp">WhatsApp dos comprovantes</label><input class="input" id="g-rcp" value="${esc(rc.phone || "")}" placeholder="(48) 99999-0000"></div>
            <div class="row wide" style="grid-column:1/-1;justify-content:flex-end"><button class="btn primary" type="submit">${I("check", "sm")}Salvar dados</button></div></form></div></section></div>`;
        $("#pl-save", el).addEventListener("click", async () => { try { const r = await A.api("set-plan", {}, { id: b.id, plan: $("#pl-plan", el).value, trial: $("#pl-trial", el).value === "1" }); b.plan = r.plan; b.trial = r.trial; CF.toast("Plano aplicado."); paint(); } catch (e) { CF.toast(e.message, "err"); } });
        // cobrança deste negócio: links (Pix manual: confirmar recebimento) e cancelar a renovação
        let blinks = [];
        const reloadPay = async () => { try { pay = ((await A.api("payments")).items || []).find((x) => x.id === b.id) || pay; b.plan = (pay && pay.plan) || b.plan; } catch (e) {} paint(); CF.adminRefreshTop(); };
        A.api("pay-links", { id: b.id }).then((r) => { blinks = r.items || []; const box = $("#pl-links", el); if (box) box.innerHTML = blinks.length ? `<b class="small">Links de pagamento</b>${linksHtml(blinks, false)}` : `<p class="small muted">Nenhum link de pagamento ainda.</p>`; })
          .catch((e) => { const box = $("#pl-links", el); if (box) box.innerHTML = `<p class="small muted">${esc(e.message)}</p>`; });
        bindLinks($("#pl-links", el), () => blinks, reloadPay);
        $("#pl-link", el).addEventListener("click", () => linkModal({ biz: Object.assign({}, b, { phone: pay && pay.phone }), onDone: reloadPay }));
        const stop = $("#pl-stop", el); if (stop) stop.addEventListener("click", () => CF.confirm({ title: "Cancelar a renovação?", text: `A assinatura ${esc((PROV[bl.provider || "stripe"] || {}).name || "")} para de cobrar. O Pro continua até ${esc(when(bl.period_end))}; depois o plano volta ao Free.`, ok: "Cancelar renovação", danger: true,
          async onOk() { try { await A.api("pay-cancel-sub", {}, { business: b.id }); CF.toast("Renovação cancelada."); reloadPay(); } catch (e) { CF.toast(e.message, "err"); } } }));
        // logo: a imagem vira um quadrado de 256 px (sem cortar) no navegador e vai embutida (data:image/…), igual ao painel do lojista
        const setLogo = async (url) => { try { const r = await A.api("update-business", {}, { id: b.id, patch: { logo_url: url } }); b.logo_url = (r.item && r.item.logo_url !== undefined) ? r.item.logo_url : url || null; CF.toast(url ? "Logo salvo." : "Logo removido."); paint(); } catch (e) { CF.toast(e.message, "err"); } };
        $("#g-logo-f", el).addEventListener("change", (e) => { const f = e.target.files[0]; e.target.value = ""; if (!f) return;
          if (!/^image\/(png|jpeg|webp)$/.test(f.type)) return CF.toast("Use PNG, JPG ou WebP.", "err"); if (f.size > 8e6) return CF.toast("Imagem muito grande (máx. 8 MB).", "err");
          const fr = new FileReader(); fr.onload = () => { const im = new Image(); im.onload = () => { const S = 256, cv = document.createElement("canvas"); cv.width = cv.height = S; const cx = cv.getContext("2d"), k = Math.min(S / im.width, S / im.height), w = im.width * k, h = im.height * k;
            cx.drawImage(im, (S - w) / 2, (S - h) / 2, w, h); let url = cv.toDataURL("image/png"); if (url.length > 300e3) url = cv.toDataURL("image/webp", 0.9); if (url.length > 300e3) url = cv.toDataURL("image/jpeg", 0.85); setLogo(url); };
            im.onerror = () => CF.toast("Não consegui abrir esta imagem.", "err"); im.src = fr.result; }; fr.readAsDataURL(f); });
        const lrm = $("#g-logo-rm", el); if (lrm) lrm.addEventListener("click", () => CF.confirm({ title: "Remover o logo?", text: "A página volta a mostrar a inicial do nome.", ok: "Remover", danger: true, onOk: () => setLogo("") }));
        $("#bz-form", el).addEventListener("submit", async (e) => { e.preventDefault(); const g = (s) => $(s, el).value;
          const patch = { name: g("#g-name").trim(), type: g("#g-type").trim(), tagline: g("#g-tag"), address: g("#g-addr"), page_color: g("#g-color"), tz: g("#g-tz").trim(), currency: g("#g-cur"), settings: { welcome: { mode: g("#g-wel"), qty: Math.max(1, Math.min(5, +g("#g-welq") || 1)) }, receipts: { on: g("#g-rc") === "1", phone: g("#g-rcp").trim() } } };
          try { const r = await A.api("update-business", {}, { id: b.id, patch }); b = Object.assign(b, r.item || patch, { settings: Object.assign({}, b.settings, patch.settings) }); CF.toast("Dados salvos."); paint(); } catch (e2) { CF.toast(e2.message, "err"); } }); };

      const card = (el) => { const cards = b.cards || [];
        el.innerHTML = `<section class="card"><div class="card-h row between wrap" style="gap:10px"><div><h2>Cartões</h2><p>Carimbos, cabeçalho e recompensa. Só um cartão fica ativo; o servidor não deixa ficar sem nenhum.</p></div><button class="btn sm" id="cd-new">${I("plus", "sm")}Novo cartão</button></div>
          <div class="card-b stack-sm" style="gap:14px" id="cd-list">${cards.map((c) => cardForm(c)).join("") || `<p class="muted">Nenhum cartão. Crie um.</p>`}</div></section>`;
        const bind = () => el.querySelectorAll("form[data-card]").forEach((f) => {
          f.addEventListener("submit", async (e) => { e.preventDefault(); const g = (s) => f.querySelector(s).value; const c = { id: f.dataset.card || undefined, name: g("[name=name]").trim(), stamps: +g("[name=stamps]"), header: g("[name=header]").trim(), reward_text: g("[name=reward_text]"), reward_label: g("[name=reward_label]").trim(), active: f.querySelector("[name=active]").checked };
            try { const r = await A.api("set-card", {}, { id: b.id, card: c }); const k = r.item; const i = (b.cards || []).findIndex((x) => x.id === k.id); if (i >= 0) b.cards[i] = k; else (b.cards = b.cards || []).push(k); if (k.active) b.cards.forEach((x) => { if (x.id !== k.id) x.active = false; }); CF.toast("Cartão salvo."); card(el); } catch (e2) { CF.toast(e2.message, "err"); } });
          const del = f.querySelector("[data-del]"); if (del) del.addEventListener("click", () => CF.confirm({ title: "Excluir este cartão?", text: "Os clientes não perdem o histórico; se ele estava ativo, o mais recente passa a ser o ativo.", ok: "Excluir", danger: true, async onOk() { try { await A.api("delete-card", {}, { id: b.id, card: f.dataset.card }); b.cards = b.cards.filter((x) => x.id !== f.dataset.card); if (!b.cards.some((x) => x.active) && b.cards.length) b.cards[b.cards.length - 1].active = true; CF.toast("Cartão excluído."); card(el); } catch (e) { CF.toast(e.message, "err"); } } }));
        });
        bind();
        $("#cd-new", el).addEventListener("click", () => { $("#cd-list", el).insertAdjacentHTML("afterbegin", cardForm({ name: b.name, stamps: 8, header: "RECOMPENSAS", reward_text: "Colete carimbos e ganhe recompensas!", reward_label: "Recompensa", active: false })); bind(); }); };
      const cardForm = (c) => `<form class="card" style="padding:16px" data-card="${esc(c.id || "")}"><div class="row between wrap" style="gap:8px;margin-bottom:10px"><b>${c.id ? esc(c.name) : "Novo cartão"}</b>${c.active ? `<span class="pill green">ativo</span>` : `<span class="pill gray">pausado</span>`}</div>
          <div class="form-grid"><div class="field"><label>Nome</label><input class="input" name="name" value="${esc(c.name || "")}" required maxlength="60"></div><div class="field"><label>Carimbos (2–20)</label><input class="input" name="stamps" type="number" min="2" max="20" value="${esc(String(c.stamps || 8))}"></div>
            <div class="field"><label>Cabeçalho</label><input class="input" name="header" value="${esc(c.header || "RECOMPENSAS")}" maxlength="30"></div><div class="field"><label>Rótulo da recompensa</label><input class="input" name="reward_label" value="${esc(c.reward_label || "")}" maxlength="60"></div>
            <div class="field wide"><label>Texto da recompensa</label><input class="input" name="reward_text" value="${esc(c.reward_text || "")}" maxlength="120"></div>
            <label class="row" style="gap:10px"><span class="toggle"><input type="checkbox" name="active" ${c.active ? "checked" : ""}><span></span></span><span>Cartão ativo (clientes novos recebem este)</span></label></div>
          <div class="row" style="justify-content:flex-end;gap:8px;margin-top:10px">${c.id ? `<button class="btn danger" type="button" data-del>${I("trash", "sm")}Excluir</button>` : ""}<button class="btn primary" type="submit">${I("check", "sm")}Salvar cartão</button></div></form>`;

      const page = (el) => { if (!b.itemsOk) { el.innerHTML = oldDb(); return; }
        items = (b.items || b.page_items || items || []).map((x) => Object.assign({}, x));
        const draw = () => { $("#it-rows", el).innerHTML = items.length ? items.map((it, i) => `<div class="item-row" data-i="${i}"><select class="select sm" data-k="type">${ITEM_TYPES.map(([k, t]) => `<option value="${k}" ${k === it.type ? "selected" : ""}>${t}</option>`).join("")}</select><input class="input sm" data-k="title" value="${esc(it.title || "")}" placeholder="Título" maxlength="80"><input class="input sm" data-k="url" value="${esc(it.url || "")}" placeholder="${["menu", "catalog", "news"].includes(it.type) ? "Link opcional (https://)" : it.type === "contact" ? "WhatsApp, telefone ou e-mail" : it.type === "wifi" ? "—" : "https://"}"><label class="check small"><input type="checkbox" data-k="icon_only" ${it.icon_only ? "checked" : ""}><span>Só ícone</span></label>
            <div class="row" style="gap:4px"><button class="icon-btn" type="button" data-mv="-1" aria-label="Subir" ${i === 0 ? "disabled" : ""}>${I("chevron-up")}</button><button class="icon-btn" type="button" data-mv="1" aria-label="Descer" ${i === items.length - 1 ? "disabled" : ""}>${I("chevron-down")}</button><button class="icon-btn" type="button" data-json aria-label="Conteúdo (itens, descrição)">${I("file")}</button><button class="icon-btn" type="button" data-del aria-label="Remover">${I("trash")}</button></div></div>`).join("") : `<p class="muted">Nenhum item na página.</p>`;
          el.querySelectorAll(".item-row").forEach((row) => { const i = +row.dataset.i;
            row.addEventListener("input", (e) => { const k = e.target.dataset.k; if (k) items[i][k] = e.target.type === "checkbox" ? e.target.checked : e.target.value; });
            row.addEventListener("change", (e) => { const k = e.target.dataset.k; if (k === "type" || k === "icon_only") { items[i][k] = e.target.type === "checkbox" ? e.target.checked : e.target.value; draw(); } });
            row.addEventListener("click", (e) => { const mv = e.target.closest("[data-mv]"); if (mv) { const j = i + +mv.dataset.mv; [items[i], items[j]] = [items[j], items[i]]; return draw(); } if (e.target.closest("[data-del]")) { items.splice(i, 1); return draw(); }
              if (e.target.closest("[data-json]")) { const it = items[i]; const ov = CF.modal({ title: `Conteúdo: ${esc(it.title || "item")}`, sub: "Descrição, rótulo do botão e a lista de itens (JSON), como o painel grava.", size: "lg", body: `<div class="field"><label for="ij-body">Descrição</label><textarea class="input" id="ij-body" rows="2">${esc(it.body || "")}</textarea></div><div class="field" style="margin-top:10px"><label for="ij-label">Rótulo do botão</label><input class="input" id="ij-label" value="${esc(it.label || "")}"></div><div class="field" style="margin-top:10px"><label for="ij-items">Itens (JSON)</label><textarea class="input" id="ij-items" rows="8" style="font-family:ui-monospace,monospace;font-size:12px">${esc(JSON.stringify(it.items || [], null, 2))}</textarea><span class="hint">Menu: [{"name","price"}] · Catálogo: [{"name","price","desc","photo"}] · Novidades: [{"image","fmt"}] · Horário: [{"dia","horas"}]</span></div>`, foot: `<button class="btn" data-close>Cancelar</button><button class="btn primary" id="ij-ok">Aplicar</button>` });
                ov.querySelector("#ij-ok").addEventListener("click", () => { try { const arr = JSON.parse(ov.querySelector("#ij-items").value || "[]"); if (!Array.isArray(arr)) throw new Error("A lista precisa ser um array."); it.items = arr; it.body = ov.querySelector("#ij-body").value; it.label = ov.querySelector("#ij-label").value; ov.close(); draw(); } catch (e2) { CF.toast("JSON inválido: " + e2.message, "err"); } }); } });
          }); };
        el.innerHTML = `<section class="card"><div class="card-h row between wrap" style="gap:10px"><div><h2>Itens da página</h2><p>Blocos que o cliente vê. A ordem da lista é a ordem na página; “Só ícone” põe o item na linha de ícones.</p></div><div class="row" style="gap:8px"><button class="btn sm" id="it-add">${I("plus", "sm")}Adicionar item</button><button class="btn primary sm" id="it-save">${I("check", "sm")}Salvar itens</button></div></div><div class="card-b" id="it-rows"></div></section>`;
        draw();
        $("#it-add", el).addEventListener("click", () => { items.push({ type: "link", title: "", url: "", body: "", label: "", items: [], icon_only: false, onsite: false }); draw(); });
        $("#it-save", el).addEventListener("click", async () => { const bad = items.find((it) => !String(it.title || "").trim() || (["link", "social", "gmaps"].includes(it.type) && it.url && !/^https:\/\//.test(it.url))); if (bad) return CF.toast("Todo item precisa de título; links só com https://.", "err");
          try { const r = await A.api("set-items", {}, { id: b.id, items }); b.items = r.items || items; CF.toast("Itens salvos."); page(el); } catch (e) { CF.toast(e.message, "err"); } }); };

      /* ---------- Sugestões: geradas por tools/ficha_jev.py (dados coletados + decisões do Jev); nada muda na página antes de aprovar */
      const SUG_KIND = { reward: ["star", "Prêmio do cartão"], item: ["plus", "Item da página"], note: ["info", "Nota interna"] };
      const sugConf = (s) => s.source === "regra" ? `<span class="pill gray" title="Conferência automática, sem modelo">regra</span>` : s.confidence == null ? "" :
        `<span class="pill ${s.confidence >= 0.85 ? "green" : s.confidence >= 0.6 ? "amber" : "gray"}" title="Certeza do Jev">Jev ${Math.round(s.confidence * 100)}%</span>`;
      const sugBody = (s) => { const p = s.proposal || {};
        if (s.kind === "reward") return `<div class="adm-sug-cmp"><div><small>Hoje</small><b>${esc((s.current || {}).reward_label || "—")}</b></div><div class="new"><small>Sugerido</small><b>${esc(p.reward_label || "")}</b></div></div>`;
        if (s.kind !== "item") return "";
        const rows = p.items || [];
        return `<div class="adm-sug-prev"><b>${esc(p.title || "")}</b>${p.body ? `<p>${esc(p.body)}</p>` : ""}${rows.length ? `<ul>${rows.slice(0, 8).map((x) => `<li><span>${esc(x.name || "")}</span><span>${esc(x.price || "")}</span></li>`).join("")}</ul>` : ""}${rows.length > 8 ? `<small>+ ${rows.length - 8} linhas</small>` : ""}${p.url ? `<small>Botão: ${esc(p.label || "Abrir")} → ${esc(p.url)}</small>` : ""}</div>`; };
      const applySug = async (s) => { const p = s.proposal || {};
        if (s.kind === "reward") { const c = (b.cards || []).find((x) => x.active) || (b.cards || [])[0]; if (!c) throw new Error("Este negócio não tem cartão.");
          const r = await A.api("set-card", {}, { id: b.id, card: { id: c.id, name: c.name, stamps: c.stamps || p.stamps || 10, header: c.header, reward_text: c.reward_text, reward_label: p.reward_label, active: c.active } });
          Object.assign(c, r.item || { reward_label: p.reward_label }); }
        if (s.kind === "item") { if (!b.itemsOk) throw new Error("O banco precisa da atualização (Atualizar banco (Supabase).bat) antes de aplicar itens.");
          const nu = { type: p.type || "menu", title: p.title, body: p.body || "", label: p.label || "", url: p.url || "", items: p.items || [], icon_only: false, onsite: false };
          const arr = b.items.slice(), at = arr.findIndex((x) => x.type === "gmaps" || x.type === "hours"); arr.splice(at < 0 ? arr.length : at, 0, nu);   // antes de "Como chegar"/"Horário"
          const r = await A.api("set-items", {}, { id: b.id, items: arr }); b.items = r.items || arr; } };
      const sug = async (el) => {
        el.innerHTML = `<p class="muted">Carregando…</p>`;
        let list; try { list = (await A.api("suggestions", { id: b.id })).items || []; } catch (e) { el.innerHTML = err(/precisa da atualiza/.test(e.message) ? "O banco precisa da atualização (Atualizar banco (Supabase).bat) para as sugestões." : e.message); return; }
        const open = list.filter((s) => s.status === "open"), done = list.filter((s) => s.status !== "open");
        b.suggestions_open = open.length;
        const cardHtml = (s) => { const k = SUG_KIND[s.kind] || SUG_KIND.note;
          return `<article class="adm-sug" data-sug="${esc(s.id)}"><div class="adm-sug-h"><span class="adm-sug-ic">${I(k[0])}</span><b>${esc(s.title)}</b><span class="adm-sug-tags"><span class="pill gray">${k[1]}</span>${sugConf(s)}</span></div>
            ${sugBody(s)}${s.evidence ? `<p class="hint">${esc(s.evidence)}</p>` : ""}
            <div class="adm-sug-a"><button class="btn sm" type="button" data-sd="rejected">${I("x", "sm")}Descartar</button><button class="btn primary sm" type="button" data-sd="approved">${I("check", "sm")}${s.kind === "note" ? "Ok, anotado" : "Aprovar e aplicar"}</button></div></article>`; };
        el.innerHTML = `<section class="card"><div class="card-h"><h2>Sugestões para a página</h2><p>Feitas com os dados coletados (site e Google) e as decisões do Jev, com a certeza de cada uma. Nada muda na página até você aprovar; notas internas só aparecem aqui.</p></div>
          <div class="card-b stack-sm" style="gap:12px">${open.map(cardHtml).join("") || `<p class="muted">Nenhuma sugestão em aberto. Para gerar: <code>python tools/ficha_jev.py negocio "nome" --site arquivo.txt --gravar</code></p>`}
          ${done.length ? `<details class="adm-sug-done"><summary>Já decididas (${done.length})</summary><ul>${done.map((s) => `<li><span class="pill ${s.status === "approved" ? "green" : "gray"}">${s.status === "approved" ? "aprovada" : "descartada"}</span><span>${esc(s.title)}</span><small class="muted">${esc(when(s.decided_at, true))}</small><button class="btn sm" type="button" data-reopen="${esc(s.id)}" title="Volta para as em aberto (o que já foi aplicado continua na página)">Reabrir</button></li>`).join("")}</ul></details>` : ""}</div></section>`;
        el.querySelectorAll("[data-sug]").forEach((art) => art.addEventListener("click", async (e) => { const btn = e.target.closest("[data-sd]"); if (!btn) return;
          const s = open.find((x) => x.id === art.dataset.sug); if (!s) return; art.querySelectorAll("button").forEach((x) => { x.disabled = true; });
          try { if (btn.dataset.sd === "approved") await applySug(s); await A.api("suggestion-decide", {}, { id: s.id, status: btn.dataset.sd });
            CF.toast(btn.dataset.sd === "rejected" ? "Sugestão descartada." : s.kind === "reward" ? "Prêmio do cartão atualizado." : s.kind === "item" ? "Item adicionado à página." : "Nota marcada como lida.");
            b.suggestions_open = Math.max(0, open.length - 1); paint(); } catch (e2) { CF.toast(e2.message, "err"); art.querySelectorAll("button").forEach((x) => { x.disabled = false; }); } }));
        el.querySelectorAll("[data-reopen]").forEach((x) => x.addEventListener("click", async () => { try { await A.api("suggestion-decide", {}, { id: x.dataset.reopen, status: "open" }); b.suggestions_open = open.length + 1; paint(); } catch (e) { CF.toast(e.message, "err"); } }));
      };

      const cust = async (el) => { el.innerHTML = `<section class="card"><div class="card-h row between wrap" style="gap:10px"><div><h2>Clientes com cartão</h2><p>Lista do negócio, com carimbos atuais e total acumulado.</p></div><button class="btn sm" id="cu-csv">${I("download", "sm")}Exportar CSV</button></div><div class="card-b" id="cu-list"><p class="muted">Carregando…</p></div></section>`;
        try { const rows = (await A.api("customers", { id: b.id })).items || [];
          $("#cu-list", el).innerHTML = rows.length ? `<div class="table-wrap"><div class="table-scroll"><table class="t"><thead><tr><th>Nome</th><th>Contato</th><th>Código</th><th>Carimbos</th><th>Total</th><th>Último carimbo</th><th>Desde</th></tr></thead><tbody>${rows.map((c) => `<tr data-row-click data-cust="${esc(c.id)}"><td><b>${esc(c.name)}</b></td><td><small>${esc(c.phone || "")}${c.phone && c.email ? " · " : ""}${esc(c.email || "")}</small></td><td><code>${esc(c.code || "")}</code></td><td>${esc(String(c.stamps || 0))}</td><td>${esc(String(c.total || 0))}</td><td>${esc(when(c.last, true))}</td><td>${esc(when(c.created_at))}</td></tr>`).join("")}</tbody></table></div></div>` : `<p class="muted">Nenhum cliente ainda.</p>`;
          $("#cu-list", el).addEventListener("click", (e) => { const tr = e.target.closest("tr[data-cust]"); if (!tr || e.target.closest("a,button,input")) return; const c = rows.find((x) => x.id === tr.dataset.cust); if (!c) return;
            const f = (k, v) => `<div class="field"><label>${k}</label><div>${v || "—"}</div></div>`;
            CF.modal({ title: esc(c.name || "Cliente"), sub: `Cliente de ${esc(b.name)} desde ${esc(when(c.created_at))}`, body: `<div class="form-grid">${f("WhatsApp / telefone", esc(c.phone || ""))}${f("E-mail", esc(c.email || ""))}${f("Código do cartão", c.code ? `<code>${esc(c.code)}</code>` : "")}${f("Aniversário", esc(c.birthday || ""))}${f("Carimbos no cartão ativo", esc(String(c.stamps || 0)))}${f("Carimbos no total", esc(String(c.total || 0)))}${f("Último carimbo", esc(when(c.last, true)))}</div>`,
              foot: `${c.phone ? `<a class="btn" href="${esc(wa(waPhone(c.phone) || c.phone, ""))}" target="_blank" rel="noopener">${I("brand:whatsapp", "sm")}WhatsApp</a>` : ""}${c.email ? `<a class="btn" href="mailto:${esc(c.email)}">${I("mail", "sm")}E-mail</a>` : ""}<button class="btn primary" data-close>Fechar</button>` }); });
          $("#cu-csv", el).addEventListener("click", () => dl(`clientes-${b.slug}.csv`, csv(rows, [["nome", "name"], ["telefone", "phone"], ["email", "email"], ["aniversario", "birthday"], ["codigo", "code"], ["carimbos", "stamps"], ["total", "total"], ["ultimo_carimbo", "last"], ["cadastro", "created_at"]]), "text/csv"));
        } catch (e) { $("#cu-list", el).innerHTML = err(e.message); } };

      const navTab = (el) => { nav = (b.nav || []).map((n) => ({ id: n.id, group_label: n.group_label || "Atendimento", label: n.label, icon: n.icon || "zap", kind: n.kind, target: n.target, active: n.active !== false }));
        const ICONS = [["zap", "Raio"], ["message", "Mensagem"], ["chat", "Conversa"], ["users", "Pessoas"], ["user-plus", "Novo contato"], ["bell", "Sino"], ["file", "Documento"], ["sparkles", "Brilho"], ["megaphone", "Megafone"], ["star", "Estrela"], ["link", "Link"], ["settings", "Engrenagem"], ["calculator", "Calculadora"], ["grid", "Painel"], ["phone", "Telefone"], ["wifi", "Wi-Fi"], ["external", "Abrir fora"], ["key", "Chave"], ["clipboard", "Prancheta"], ["gift", "Presente"], ["clock", "Relógio"], ["calendar", "Calendário"], ["heart", "Coração"], ["tag", "Etiqueta"]];
        const icName = (ic) => (ICONS.find((x) => x[0] === ic) || [ic, ic])[1], VIEWS = [["overview", "Resumo do chatbot"], ["conversations", "Conversas"], ["leads", "Leads"], ["tickets", "Atendimento humano"], ["kb", "Base de conhecimento"], ["agente", "Agente"], ["campanas", "Campanhas"], ["insights", "Insights"], ["conexiones", "Conexões"], ["config", "Configurações"], ["costs", "Custos"]];
        const draw = () => { $("#nv-rows", el).innerHTML = nav.length ? `<div class="item-row nv-head" aria-hidden="true" style="grid-template-columns:1fr 1.3fr 130px 140px 1.5fr auto"><span>Grupo no menu</span><span>Nome do item</span><span>Ícone</span><span>Tipo</span><span>O que abre</span><span>Ativo · ordem</span></div>` + nav.map((n, i) => `<div class="item-row" data-i="${i}" style="grid-template-columns:1fr 1.3fr 130px 140px 1.5fr auto"><input class="input sm" data-k="group_label" value="${esc(n.group_label)}" placeholder="Grupo" aria-label="Grupo no menu"><input class="input sm" data-k="label" value="${esc(n.label)}" placeholder="Nome no menu" maxlength="40" aria-label="Nome do item"><button type="button" class="btn sm nv-ic" data-pick aria-label="Ícone: ${esc(icName(n.icon))} (trocar)">${I(n.icon, "sm")}<span>${esc(icName(n.icon))}</span></button><select class="select sm" data-k="kind" aria-label="Tipo"><option value="forja" ${n.kind === "forja" ? "selected" : ""}>Tela do chatbot</option><option value="url" ${n.kind === "url" ? "selected" : ""}>Link externo</option><option value="route" ${n.kind === "route" ? "selected" : ""}>Tela do painel</option></select>${n.kind === "forja" ? `<select class="select sm" data-k="target">${VIEWS.map(([k, t]) => `<option value="${k}" ${k === n.target ? "selected" : ""}>${t}</option>`).join("")}</select>` : `<input class="input sm" data-k="target" value="${esc(n.target || "")}" placeholder="${n.kind === "url" ? "https://…" : "/integrations"}">`}
            <div class="row" style="gap:4px"><label class="check small" title="Ativo"><input type="checkbox" data-k="active" ${n.active ? "checked" : ""}><span class="sr-only">Ativo</span></label><button class="icon-btn" type="button" data-mv="-1" aria-label="Subir" ${i === 0 ? "disabled" : ""}>${I("chevron-up")}</button><button class="icon-btn" type="button" data-mv="1" aria-label="Descer" ${i === nav.length - 1 ? "disabled" : ""}>${I("chevron-down")}</button><button class="icon-btn" type="button" data-del aria-label="Remover">${I("trash")}</button></div></div>`).join("") : `<p class="muted">Nenhum item. Use “Pacote Forja padrão” ou “Adicionar item”.</p>`;
          el.querySelectorAll(".item-row[data-i]").forEach((row) => { const i = +row.dataset.i; row.addEventListener("input", (e) => { const k = e.target.dataset.k; if (!k) return; nav[i][k] = e.target.type === "checkbox" ? e.target.checked : e.target.value; if (k === "kind") { nav[i].target = e.target.value === "forja" ? "overview" : ""; draw(); } });
            row.addEventListener("change", (e) => { const k = e.target.dataset.k; if (["kind", "icon", "active"].includes(k) || (k === "target" && e.target.tagName === "SELECT")) { nav[i][k] = e.target.type === "checkbox" ? e.target.checked : e.target.value; if (k === "kind") { nav[i].target = e.target.value === "forja" ? "overview" : ""; draw(); } } });
            row.addEventListener("click", (e) => { if (e.target.closest("[data-pick]")) {   // escolher o ícone vendo o desenho
                const ov = CF.modal({ title: "Ícone do item", sub: "Aparece ao lado do nome no menu lateral do lojista.", body: `<div class="nv-icgrid">${ICONS.map(([ic, nm]) => `<button type="button" class="nv-icopt ${ic === nav[i].icon ? "on" : ""}" data-ic="${ic}">${I(ic)}<span>${esc(nm)}</span></button>`).join("")}</div>` });
                ov.querySelectorAll("[data-ic]").forEach((bt) => bt.addEventListener("click", () => { nav[i].icon = bt.dataset.ic; ov.close(); draw(); })); return; }
              const mv = e.target.closest("[data-mv]"); if (mv) { const j = i + +mv.dataset.mv; [nav[i], nav[j]] = [nav[j], nav[i]]; return draw(); } if (e.target.closest("[data-del]")) { nav.splice(i, 1); draw(); } }); }); };
        el.innerHTML = `<section class="card"><div class="card-h row between wrap" style="gap:10px"><div><h2>Menu do painel do lojista</h2><p>Itens extras no menu lateral deste cliente (ex.: telas do chatbot). Até 12.</p></div><div class="row" style="gap:8px"><button class="btn sm" id="nv-preset" ${b.forja ? "" : "disabled title='Vincule o chatbot antes'"}>${I("sparkles", "sm")}Pacote Forja padrão</button><button class="btn sm" id="nv-add">${I("plus", "sm")}Adicionar item</button><button class="btn primary sm" id="nv-save">${I("check", "sm")}Salvar menu</button></div></div><div class="card-b" id="nv-rows"></div></section>`;
        draw();
        $("#nv-add", el).addEventListener("click", () => { if (nav.length >= 12) return CF.toast("Limite de 12 itens.", "err"); nav.push({ group_label: "Atendimento", label: "", icon: "zap", kind: b.forja ? "forja" : "url", target: b.forja ? "overview" : "", active: true }); draw(); });
        $("#nv-preset", el).addEventListener("click", () => { [["Resumo do chatbot", "grid", "overview"], ["Conversas", "message", "conversations"], ["Leads do chatbot", "user-plus", "leads"], ["Base de conhecimento", "file", "kb"]].forEach(([label, icon, target]) => { if (!nav.some((n) => n.kind === "forja" && n.target === target) && nav.length < 12) nav.push({ group_label: "Atendimento", label, icon, kind: "forja", target, active: true }); }); draw(); });
        $("#nv-save", el).addEventListener("click", async () => { const bad = nav.find((n) => !n.label.trim() || !n.target.trim() || (n.kind === "url" && !/^https:\/\//.test(n.target)) || (n.kind === "route" && !/^\//.test(n.target))); if (bad) return CF.toast("Preencha rótulo e destino (links só https://, rotas começam com /).", "err");
          try { const r = await A.api("set-nav", {}, { id: b.id, items: nav }); b.nav = r.items || nav; b.nav_count = b.nav.length; CF.toast("Menu salvo."); navTab(el); } catch (e) { CF.toast(e.message, "err"); } }); };

      const forja = (el) => { const f = b.forja, m = f && f.last_metrics;
        el.innerHTML = `<section class="card"><div class="card-h row between wrap" style="gap:10px"><div><h2>Chatbot (Forja)</h2><p>Bot de IA do cliente no Cloudflare. O token fica só no servidor.</p></div>${f ? forjaPill(f) : ""}</div><div class="card-b stack-sm" style="gap:14px">
          ${f ? `<div class="row wrap" style="gap:16px;align-items:center"><div><b>${esc(f.name)}</b><br><a class="small" href="${esc(f.base_url)}/admin" target="_blank" rel="noopener">${esc(f.base_url)}/admin ${I("external", "xs")}</a></div><div class="small muted">Plano do bot: <b>${f.tier === "pro" ? "Pro" : "Free"}</b> · Token: <b>${f.has_token ? "cadastrado" : "falta"}</b> · Último contato: <b>${esc(when(f.last_seen_at, true))}</b></div><div class="row" style="gap:8px;margin-left:auto"><select class="select" id="fj-range" aria-label="Período"><option value="7d">7 dias</option><option value="30d">30 dias</option><option value="all">Tudo</option></select><button class="btn" id="fj-poll">${I("refresh", "sm")}Consultar agora</button></div></div>${f.last_error ? err(f.last_error) : ""}
            <div class="stat-inline">${m ? `<div><b>${esc(String(m.conversations ?? 0))}</b><span>conversas</span></div><div><b>${esc(String(m.messages ?? 0))}</b><span>mensagens</span></div><div><b>${esc(String(m.leads ?? 0))}</b><span>leads</span></div><div><b>${esc(String(m.health_score ?? 100))}%</b><span>sem precisar de humano</span></div>` : `<p class="muted small">Ainda sem métricas.</p>`}</div>` : `<p class="muted">Este negócio ainda não tem chatbot vinculado.</p>`}
          <details class="adm-form"><summary class="btn ghost sm" style="display:inline-flex">${I(f ? "pencil" : "plus", "sm")}${f ? "Alterar vínculo" : "Vincular um bot Forja"}</summary><form class="form-grid" id="fj-form" style="margin-top:12px"><div class="field"><label for="fj-name">Nome do bot</label><input class="input" id="fj-name" required maxlength="60" value="${esc(f ? f.name : "")}"></div><div class="field"><label for="fj-url">URL do Worker (https)</label><input class="input" id="fj-url" type="url" required value="${esc(f ? f.base_url : "")}" placeholder="https://cafe.workers.dev"></div><div class="field"><label for="fj-token">CONTROL_PLANE_TOKEN ${f && f.has_token ? "(em branco mantém)" : ""}</label><input class="input" id="fj-token" type="password" autocomplete="new-password"></div><div class="field"><label for="fj-tier">Plano do bot</label><select class="select" id="fj-tier"><option value="free" ${f && f.tier === "free" ? "selected" : ""}>Free</option><option value="pro" ${f && f.tier === "pro" ? "selected" : ""}>Pro</option></select></div><div class="row wide" style="grid-column:1/-1;justify-content:flex-end;gap:8px">${f ? `<button class="btn danger" type="button" id="fj-rm">${I("trash", "sm")}Desvincular</button>` : ""}<button class="btn primary" type="submit">${I("check", "sm")}Salvar vínculo</button></div></form></details></div></section>`;
        const pf = $("#fj-poll", el); if (pf) pf.addEventListener("click", async () => { pf.disabled = true; try { const r = await A.api("forja-metrics", { id: b.id, range: $("#fj-range", el).value }); if (!r.ok) throw new Error(r.error || "Sem resposta."); b.forja = Object.assign(b.forja || {}, r.instance, { last_metrics: r.data, last_error: null, has_token: true }); CF.toast("Métricas atualizadas."); forja(el); } catch (e) { CF.toast(e.message, "err"); pf.disabled = false; } });
        $("#fj-form", el).addEventListener("submit", async (e) => { e.preventDefault(); try { const r = await A.api("forja-upsert", {}, { id: b.id, name: $("#fj-name", el).value.trim(), base_url: $("#fj-url", el).value.trim(), token: $("#fj-token", el).value, tier: $("#fj-tier", el).value }); b.forja = r.item; CF.toast("Chatbot vinculado."); forja(el); } catch (e2) { CF.toast(e2.message, "err"); } });
        const rm = $("#fj-rm", el); if (rm) rm.addEventListener("click", () => CF.confirm({ title: "Desvincular o chatbot?", text: "O token é apagado e os itens de menu do tipo Forja saem do painel do cliente.", ok: "Desvincular", danger: true, async onOk() { try { await A.api("forja-remove", {}, { id: b.id }); b.forja = null; b.nav = (b.nav || []).filter((n) => n.kind !== "forja"); CF.toast("Chatbot desvinculado."); forja(el); } catch (e) { CF.toast(e.message, "err"); } } })); };

      const model = (el) => { el.innerHTML = `<div class="grid g2" style="gap:16px;align-items:start"><section class="card"><div class="card-h"><h2>Exportar este negócio como modelo</h2><p>JSON com dados da página, cartões e itens — para replicar em franquias e filiais. Não leva clientes nem pagamentos.</p></div><div class="card-b stack-sm" style="gap:10px"><button class="btn primary" id="md-exp">${I("download", "sm")}Baixar modelo (.json)</button><pre class="json" id="md-pre">…</pre></div></section>
          <section class="card"><div class="card-h"><h2>Aplicar um modelo aqui</h2><p>Cole ou envie o JSON de outro negócio. “Substituir” apaga os itens e cartões atuais antes.</p></div><div class="card-b stack-sm" style="gap:10px"><input type="file" id="md-file" accept="application/json,.json" class="sr-only"><label for="md-file" class="drop" id="md-drop">${I("upload")} Arraste o arquivo .json aqui ou clique para escolher</label><textarea class="input" id="md-txt" rows="6" placeholder='{"version":1,"business":{…},"cards":[…],"page_items":[…]}' style="font-family:ui-monospace,monospace;font-size:12px"></textarea><label class="check"><input type="checkbox" id="md-rep"><span>Substituir itens e cartões atuais</span></label><div class="row" style="justify-content:flex-end"><button class="btn primary" id="md-imp">${I("check", "sm")}Aplicar modelo</button></div></div></section></div>`;
        A.api("export", { id: b.id }).then((r) => { $("#md-pre", el).textContent = JSON.stringify(r.model, null, 2).slice(0, 4000); $("#md-exp", el).addEventListener("click", () => dl(`modelo-${b.slug}.json`, JSON.stringify(r.model, null, 2), "application/json")); }).catch((e) => { $("#md-pre", el).textContent = e.message; });
        bindJsonDrop(el, "#md-drop", "#md-file", (txt) => { $("#md-txt", el).value = txt; });
        $("#md-imp", el).addEventListener("click", async () => { let m; try { m = JSON.parse($("#md-txt", el).value); } catch (e) { return CF.toast("JSON inválido.", "err"); } try { const r = await A.api("import", {}, { id: b.id, model: m, replace: $("#md-rep", el).checked }); CF.toast(`Modelo aplicado: ${r.cards || 0} cartões e ${r.items || 0} itens.`); const d = await A.api("business", { id: b.id }); b = d.item; b.itemsOk = Array.isArray(b.items) || Array.isArray(b.page_items); b.items = b.items || b.page_items || []; tab = "page"; paint(); } catch (e) { CF.toast(e.message, "err"); } }); };

      root.addEventListener("click", (e) => { const t = e.target.closest("[data-tab]"); if (t) { tab = t.dataset.tab; history.replaceState(null, "", `#/businesses/${id}?tab=${tab}`); drawTab(); } });
      try { const d = await A.api("business", { id }); b = d.item; b.itemsOk = Array.isArray(b.items) || Array.isArray(b.page_items); b.items = b.items || b.page_items || []; try { pay = ((await A.api("payments")).items || []).find((x) => x.id === b.id) || null; if (pay && pay.billing) events = (await A.api("events", { id: b.id })).items || []; } catch (e) {} paint(); }
      catch (e) { root.innerHTML = err(e.message); }
    } }));

  /* ============================================================ Criar / importar */
  const parseCsv = (txt) => { const rows = []; let row = [], cell = "", q = false; const s = txt.replace(/^﻿/, ""); for (let i = 0; i < s.length; i++) { const c = s[i]; if (q) { if (c === '"') { if (s[i + 1] === '"') { cell += '"'; i++; } else q = false; } else cell += c; } else if (c === '"') q = true; else if (c === "," || c === ";" || c === "\t") { row.push(cell); cell = ""; } else if (c === "\n" || c === "\r") { if (c === "\r" && s[i + 1] === "\n") i++; row.push(cell); rows.push(row); row = []; cell = ""; } else cell += c; } if (cell || row.length) { row.push(cell); rows.push(row); }
    const head = (rows.shift() || []).map((h) => h.trim().toLowerCase()); const col = (names) => head.findIndex((h) => names.includes(h));
    const ci = { email: col(["email", "e-mail", "email_dono", "dono"]), name: col(["nome", "name", "negocio", "negócio", "empresa", "estabelecimento"]), plan: col(["plano", "plan"]), trial: col(["teste", "trial"]) };
    return rows.filter((r) => r.some((x) => x && x.trim())).map((r) => ({ email: (r[ci.email] || "").trim(), name: (r[ci.name] || "").trim(), plan: /pro/i.test(r[ci.plan] || "") ? "pro" : "free", trial: ci.trial < 0 ? true : !/^(n|nao|não|0|false|off)$/i.test((r[ci.trial] || "").trim()) })); };
  const bindJsonDrop = (el, dropSel, fileSel, onText) => { const drop = $(dropSel, el), file = $(fileSel, el); const read = (f) => { if (!f) return; const fr = new FileReader(); fr.onload = () => onText(String(fr.result || "")); fr.readAsText(f); };
    file.addEventListener("change", () => { read(file.files[0]); file.value = ""; }); ["dragenter", "dragover"].forEach((ev) => drop.addEventListener(ev, (e) => { e.preventDefault(); drop.classList.add("over"); })); ["dragleave", "drop"].forEach((ev) => drop.addEventListener(ev, (e) => { e.preventDefault(); drop.classList.remove("over"); })); drop.addEventListener("drop", (e) => read(e.dataTransfer.files[0])); };
  const resultsHtml = (res) => `<div class="table-wrap"><div class="table-scroll"><table class="t" style="min-width:0"><thead><tr><th>E-mail</th><th>Resultado</th><th>Negócio</th><th>Acesso</th></tr></thead><tbody>${res.map((r) => `<tr><td>${esc(r.email || "")}</td><td>${r.ok ? `<span class="pill green">criado</span>` : `<span class="pill red">${esc(r.error || "erro")}</span>`}</td><td>${r.ok ? `<a href="#/businesses/${esc(r.business_id)}">${esc(r.slug)}</a>` : ""}</td><td class="small">${r.ok ? (r.invited ? "convite enviado por e-mail" : r.link ? `dono já tinha conta — <a href="${esc(r.link)}" target="_blank" rel="noopener">link de acesso</a> (copie e envie)` : "dono já tinha conta") : ""}</td></tr>`).join("")}</tbody></table></div></div>`;
  route("/create", () => ({ title: "Criar / importar estabelecimentos", sub: "Três caminhos: um por e-mail, vários por planilha, ou aplicar um modelo (JSON) a um negócio existente.", nav: "new",
    html: `<div class="stack"><div class="tabs" role="tablist"><button type="button" class="on" data-ct="one">Por e-mail</button><button type="button" data-ct="csv">Planilha (CSV)</button><button type="button" data-ct="json">Modelo (JSON)</button></div><div id="ct"></div>${srcNote()}</div>`,
    mount(v) { let model = null, ct = "one";
      const modelBox = (id) => `<details><summary class="small" style="cursor:pointer">Usar um modelo (JSON) para o novo negócio — opcional</summary><div class="stack-sm" style="gap:8px;margin-top:8px"><input type="file" id="${id}-mf" accept="application/json,.json" class="sr-only"><label for="${id}-mf" class="drop" id="${id}-md">${I("upload")} Arraste o modelo .json aqui ou clique para escolher</label><p class="small muted" id="${id}-mi">${model ? `Modelo carregado: ${esc((model.business || {}).name || "")} · ${(model.cards || []).length} cartões · ${(model.page_items || []).length} itens` : "Nenhum modelo carregado."}</p></div></details>`;
      const bindModel = (el, id) => bindJsonDrop(el, `#${id}-md`, `#${id}-mf`, (txt) => { try { model = JSON.parse(txt); $(`#${id}-mi`, el).textContent = `Modelo carregado: ${(model.business || {}).name || ""} · ${(model.cards || []).length} cartões · ${(model.page_items || []).length} itens`; } catch (e) { CF.toast("JSON inválido.", "err"); } });
      const draw = () => { const el = $("#ct", v); v.querySelectorAll("[data-ct]").forEach((x) => x.classList.toggle("on", x.dataset.ct === ct));
        if (ct === "one") { el.innerHTML = `<section class="card"><div class="card-h"><h2>Criar um estabelecimento</h2><p>A conta do dono é criada e um convite com link de acesso vai por e-mail. O negócio já nasce pronto (com cartão).</p></div><div class="card-b stack-sm" style="gap:12px"><form class="form-grid" id="one"><div class="field"><label for="o-name">Nome do negócio</label><input class="input" id="o-name" required maxlength="100" placeholder="Café da Praça"></div><div class="field"><label for="o-email">E-mail do dono</label><input class="input" id="o-email" type="email" required placeholder="dono@exemplo.com.br"></div><div class="field"><label for="o-plan">Plano</label><select class="select" id="o-plan"><option value="free">Free</option><option value="pro">Pro</option></select></div><div class="field"><label for="o-trial">Teste grátis</label><select class="select" id="o-trial"><option value="1">Ligado</option><option value="0">Desligado</option></select></div><div class="wide" style="grid-column:1/-1">${modelBox("o")}</div><div class="row wide" style="grid-column:1/-1;justify-content:flex-end"><button class="btn primary" type="submit">${I("plus", "sm")}Criar estabelecimento</button></div></form><div id="one-res"></div></div></section>`;
          bindModel(el, "o"); $("#one", el).addEventListener("submit", async (e) => { e.preventDefault(); const bt = e.target.querySelector("button[type=submit]"); bt.disabled = true; try { const r = await A.api("create-business", {}, { email: $("#o-email", el).value.trim(), name: $("#o-name", el).value.trim(), plan: $("#o-plan", el).value, trial: $("#o-trial", el).value === "1", model }); $("#one-res", el).innerHTML = resultsHtml(r.results || []); if (r.ok) CF.toast("Estabelecimento criado."); } catch (e2) { CF.toast(e2.message, "err"); } finally { bt.disabled = false; } }); }
        else if (ct === "csv") { el.innerHTML = `<section class="card"><div class="card-h"><h2>Vários de uma vez (planilha)</h2><p>CSV com as colunas <code>nome</code>, <code>email</code> e, opcionais, <code>plano</code> (free/pro) e <code>teste</code> (sim/não). Até 50 por envio.</p></div><div class="card-b stack-sm" style="gap:12px"><input type="file" id="c-file" accept=".csv,text/csv" class="sr-only"><label for="c-file" class="drop" id="c-drop">${I("upload")} Arraste a planilha .csv aqui ou clique para escolher</label><textarea class="input" id="c-txt" rows="5" placeholder="nome;email;plano;teste&#10;Café da Praça;dono@exemplo.com.br;pro;não" style="font-family:ui-monospace,monospace;font-size:12px"></textarea>${modelBox("c")}<div class="row between wrap" style="gap:8px"><button class="btn" id="c-prev">${I("search", "sm")}Conferir</button><button class="btn primary" id="c-go" disabled>${I("plus", "sm")}Criar todos</button></div><div id="c-out"></div></div></section>`;
          let rows = []; bindJsonDrop(el, "#c-drop", "#c-file", (txt) => { $("#c-txt", el).value = txt; }); bindModel(el, "c");
          $("#c-prev", el).addEventListener("click", () => { rows = parseCsv($("#c-txt", el).value); const bad = rows.filter((r) => !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(r.email) || !r.name); $("#c-out", el).innerHTML = rows.length ? `<p class="small muted">${rows.length} linhas · ${bad.length} com problema</p><div class="table-wrap"><div class="table-scroll"><table class="t" style="min-width:0"><thead><tr><th>Nome</th><th>E-mail</th><th>Plano</th><th>Teste</th><th></th></tr></thead><tbody>${rows.map((r) => `<tr><td>${esc(r.name)}</td><td>${esc(r.email)}</td><td>${r.plan}</td><td>${r.trial ? "sim" : "não"}</td><td>${bad.includes(r) ? `<span class="pill red">confira</span>` : `<span class="pill green">ok</span>`}</td></tr>`).join("")}</tbody></table></div></div>` : `<p class="muted">Nenhuma linha encontrada.</p>`; $("#c-go", el).disabled = !rows.length || !!bad.length; });
          $("#c-go", el).addEventListener("click", async () => { $("#c-go", el).disabled = true; try { const r = await A.api("create-business", {}, { rows: rows.slice(0, 50), model }); $("#c-out", el).innerHTML = resultsHtml(r.results || []); CF.toast(r.ok ? "Todos criados." : "Alguns não foram criados; veja a lista.", r.ok ? "ok" : "err"); } catch (e) { CF.toast(e.message, "err"); $("#c-go", el).disabled = false; } }); }
        else { el.innerHTML = `<section class="card"><div class="card-h"><h2>Aplicar um modelo a um negócio existente</h2><p>Exporte o modelo em Negócios → Exportar / modelo e aplique aqui em outro negócio (franquia, filial).</p></div><div class="card-b stack-sm" style="gap:12px"><div class="field"><label for="j-biz">Negócio de destino</label><select class="select" id="j-biz"><option>Carregando…</option></select></div><input type="file" id="j-file" accept="application/json,.json" class="sr-only"><label for="j-file" class="drop" id="j-drop">${I("upload")} Arraste o modelo .json aqui ou clique para escolher</label><textarea class="input" id="j-txt" rows="6" style="font-family:ui-monospace,monospace;font-size:12px"></textarea><label class="check"><input type="checkbox" id="j-rep"><span>Substituir itens e cartões atuais</span></label><div class="row" style="justify-content:flex-end"><button class="btn primary" id="j-go">${I("check", "sm")}Aplicar</button></div></div></section>`;
          A.api("businesses").then((r) => { $("#j-biz", el).innerHTML = (r.items || []).map((b) => `<option value="${esc(b.id)}">${esc(b.name)} (${esc(b.slug)})</option>`).join(""); }); bindJsonDrop(el, "#j-drop", "#j-file", (txt) => { $("#j-txt", el).value = txt; });
          $("#j-go", el).addEventListener("click", async () => { let m; try { m = JSON.parse($("#j-txt", el).value); } catch (e) { return CF.toast("JSON inválido.", "err"); } try { const r = await A.api("import", {}, { id: $("#j-biz", el).value, model: m, replace: $("#j-rep", el).checked }); CF.toast(`Modelo aplicado: ${r.cards || 0} cartões e ${r.items || 0} itens.`); go("/businesses/" + $("#j-biz", el).value + "?tab=page"); } catch (e) { CF.toast(e.message, "err"); } }); } };
      v.addEventListener("click", (e) => { const t = e.target.closest("[data-ct]"); if (t) { ct = t.dataset.ct; draw(); } }); draw(); } }));

  /* ============================================================ Exportar */
  /* ============================================================ Prospecção: páginas em preparação + preparar a partir da base do Prospector */
  const prosPill = (p, c) => !p ? "" : p.status === "preview" ? (c && c.expires_at && new Date(c.expires_at) < new Date() ? `<span class="pill red">link expirado</span>` : `<span class="pill amber">em preparação</span>`) : `<span class="pill green">ativada</span>`;
  route("/prospects", () => ({ title: "Prospecção", sub: "Páginas preparadas para estabelecimentos que ainda não são clientes: ficam no ar como demonstração, sem cadastro, até o dono ativar pelo link.", nav: "pros",
    actions: `<button class="btn" id="pr-csv">${I("download", "sm")}Exportar CSV</button>`,
    html: `<div class="stack">
      <div class="kpis" id="pr-k"></div>
      <section class="card"><div class="card-h row between wrap" style="gap:10px"><div><h2>Páginas preparadas</h2><p>“Novo link” gera o link de ativação e a mensagem de WhatsApp (o anterior deixa de valer).</p></div>
          <div class="row" style="gap:8px"><select class="select" id="pr-f" aria-label="Situação" style="max-width:190px"><option value="">Todas</option><option value="preview">Em preparação</option><option value="claimed">Ativadas</option></select><input class="input" id="pr-q" type="search" placeholder="Buscar" aria-label="Buscar" style="max-width:220px"></div></div>
        <div class="card-b"><div id="pr-list"><p class="muted">Carregando…</p></div></div></section>
      <section class="card" id="pr-base"><div class="card-h"><h2>Preparar a partir da base do Prospector</h2><p>Escolha estabelecimentos da base do Google Maps (data/prospeccao.json) e crie as páginas. Só com o servidor local.</p></div>
        <div class="card-b stack-sm" style="gap:12px"><div class="row wrap" style="gap:8px;align-items:flex-end">
            <div class="field" style="min-width:170px"><label for="pb-c">Cidade</label><select class="select" id="pb-c"><option value="Itapema">Itapema</option></select></div>
            <div class="field" style="min-width:170px"><label for="pb-g">Grupo</label><select class="select" id="pb-g"><option value="">Todos</option></select></div>
            <div class="field" style="min-width:200px"><label for="pb-t">Nome</label><input class="input" id="pb-t" type="search" placeholder="Buscar pelo nome"></div>
            <label class="check small"><input type="checkbox" id="pb-s" checked><span>Sem site</span></label><label class="check small"><input type="checkbox" id="pb-b" checked><span>Bem avaliados</span></label><label class="check small"><input type="checkbox" id="pb-r" checked><span>Fora de redes</span></label>
            <button class="btn" type="button" id="pb-go">${I("search", "sm")}Buscar</button></div>
          <div id="pb-list"></div>
          <div class="field" style="max-width:520px"><label for="pb-app">Endereço público do app (usado nos links)</label><input class="input" id="pb-app" value="${esc(APP_URL())}"></div></div></section>
      ${srcNote()}</div>`,
    async mount(v) {
      let items = [];
      const draw = () => { const f = $("#pr-f", v).value, q = ($("#pr-q", v).value || "").toLowerCase();
        const rows = items.filter((x) => (!f || (x.prospect && x.prospect.status === f)) && (!q || (x.name || "").toLowerCase().includes(q)));
        const pre = items.filter((x) => x.prospect && x.prospect.status === "preview");
        $("#pr-k", v).innerHTML = [["Páginas preparadas", items.length], ["Em preparação", pre.length], ["Ativadas", items.length - pre.length], ["Links expirados", pre.filter((x) => x.claim && new Date(x.claim.expires_at) < new Date()).length]].map(([k, n]) => `<div class="kpi"><div class="k">${k}</div><div class="v">${n}</div></div>`).join("");
        $("#pr-list", v).innerHTML = rows.length ? `<div class="table-wrap"><div class="table-scroll"><table class="t"><thead><tr><th>Estabelecimento</th><th>Segmento</th><th>Google</th><th>Situação</th><th>Link vale até</th><th>Clientes</th><th></th></tr></thead><tbody>
          ${rows.map((x) => { const p = x.prospect || {}, c = x.claim || {}; return `<tr><td><b>${esc(x.name)}</b><br><small class="muted">${esc(x.slug)}${p.status === "claimed" ? " · ativada por " + esc((c.claimed_by || x.owner_email) || "") : ""}</small></td><td>${esc(p.segmento || "—")}</td><td>${p.rating ? `★ ${esc(String(p.rating))} · ${esc(String(p.reviews || 0))}` : "—"}</td><td>${prosPill(p, c)}</td><td>${p.status === "preview" ? esc(when(c.expires_at)) : esc(when(c.claimed_at))}</td><td>${esc(String(x.customers || 0))}</td>
            <td><div class="row" style="gap:6px;justify-content:flex-end"><a class="btn sm ghost" href="${esc(pageUrl(x.slug))}" target="_blank" rel="noopener" title="Ver página">${I("external", "sm")}</a>${p.status === "preview" ? `<button class="btn sm" type="button" data-claim="${esc(x.id)}">${I("sparkles", "sm")}Novo link</button>` : ""}<a class="btn sm" href="#/businesses/${esc(x.id)}?tab=acesso">Abrir</a></div></td></tr>`; }).join("")}</tbody></table></div></div>` : `<p class="muted">Nenhuma página preparada${f || q ? " com esse filtro" : ""}.</p>`; };
      const load = async () => { try { items = (await A.api("prospects")).items || []; draw(); } catch (e) { $("#pr-list", v).innerHTML = err(e.message); } };
      v.addEventListener("click", (e) => { const c = e.target.closest("[data-claim]"); if (!c) return; const x = items.find((y) => y.id === c.dataset.claim); if (x) CF.confirm({ title: "Gerar novo link de ativação?", text: "O link anterior deixa de valer.", ok: "Gerar", onOk: () => claimModal(x) }); });
      $("#pr-f", v).addEventListener("change", draw); $("#pr-q", v).addEventListener("input", CF.debounce(draw, 120));
      $("#pr-csv").addEventListener("click", () => dl("prospeccao-paginas.csv", csv(items, [["estabelecimento", "name"], ["slug", "slug"], ["pagina", (r) => pageUrl(r.slug)], ["segmento", (r) => (r.prospect || {}).segmento || ""], ["whatsapp", (r) => (r.prospect || {}).whatsapp || ""], ["nota", (r) => (r.prospect || {}).rating || ""], ["avaliacoes", (r) => (r.prospect || {}).reviews || ""], ["situacao", (r) => ((r.prospect || {}).status === "preview" ? "em preparação" : "ativada")], ["link_vale_ate", (r) => (r.claim || {}).expires_at || ""], ["ativada_em", (r) => (r.claim || {}).claimed_at || ""], ["clientes", "customers"]]), "text/csv"));
      $("#pb-app", v).addEventListener("change", (e) => { try { const val = e.target.value.trim(); if (/^https:\/\//.test(val)) { localStorage.setItem("cf.admin.appurl", val); CF.toast("Endereço salvo."); draw(); } else CF.toast("Use um endereço https://", "err"); } catch (x) {} });
      // base do Prospector (servidor local)
      let leads = [];
      const pb = $("#pb-list", v);
      const search = async () => {
        pb.innerHTML = `<p class="muted">Buscando…</p>`;
        try { const r = await A.api("leads", { cidade: $("#pb-c", v).value, grupo: $("#pb-g", v).value, q: $("#pb-t", v).value, sem_site: $("#pb-s", v).checked ? "1" : "", bons: $("#pb-b", v).checked ? "1" : "", sem_rede: $("#pb-r", v).checked ? "1" : "", limite: 300 });
          leads = r.items || [];
          if (r.cidades && $("#pb-c", v).options.length < 2) $("#pb-c", v).innerHTML = r.cidades.map((c) => `<option ${c === "Itapema" ? "selected" : ""}>${esc(c)}</option>`).join("");
          if (r.grupos && $("#pb-g", v).options.length < 2) $("#pb-g", v).innerHTML = `<option value="">Todos</option>` + r.grupos.map((g) => `<option>${esc(g)}</option>`).join("");
          pb.innerHTML = leads.length ? `<p class="small muted">${r.total} encontrados${r.total > leads.length ? ` (mostrando ${leads.length})` : ""}. Os já preparados vêm marcados.</p>
            <div class="table-wrap"><div class="table-scroll"><table class="t"><thead><tr><th><input type="checkbox" id="pb-all" aria-label="Selecionar todos"></th><th>Nome</th><th>Segmento</th><th>Nota</th><th>Aval.</th><th>Site</th><th>WhatsApp</th></tr></thead><tbody>
            ${leads.map((l) => `<tr><td><input type="checkbox" data-lead="${esc(l.id)}" ${l.preparado ? "disabled title='Já preparado'" : ""} aria-label="Selecionar ${esc(l.nome)}"></td><td><b>${esc(l.nome)}</b>${l.preparado ? ` <span class="pill green">preparado</span>` : ""}${l.rede ? ` <small class="muted">rede ${esc(String(l.rede_unidades))}</small>` : ""}</td><td>${esc(l.segmento)}</td><td>${l.rating || "—"}</td><td>${l.rating ? esc(String(l.reviews)) : "—"}</td><td>${l.site ? "sim" : "não"}</td><td>${esc(l.whatsapp || "")}</td></tr>`).join("")}</tbody></table></div></div>
            <div class="row" style="justify-content:flex-end;margin-top:10px"><button class="btn primary" type="button" id="pb-prep">${I("sparkles", "sm")}Preparar selecionados</button></div><div id="pb-out"></div>` : `<p class="muted">Nada encontrado com esses filtros.</p>`;
          const all = $("#pb-all", v); if (all) all.addEventListener("change", () => v.querySelectorAll("[data-lead]:not(:disabled)").forEach((c) => { c.checked = all.checked; }));
          const prep = $("#pb-prep", v); if (prep) prep.addEventListener("click", async () => {
            const ids = [...v.querySelectorAll("[data-lead]:checked")].map((c) => c.dataset.lead); if (!ids.length) return CF.toast("Selecione pelo menos um.", "err");
            prep.disabled = true; prep.textContent = `Preparando ${ids.length}…`;
            try { const res = await A.api("prepare-leads", {}, { ids, app_url: APP_URL() }); const ok = (res.results || []).filter((x) => x.ok);
              $("#pb-out", v).innerHTML = `<p class="small" style="margin-top:12px"><b>${ok.length} páginas</b> prontas${ok.some((x) => x.existing) ? " (algumas já existiam: gere o link em Páginas preparadas)" : ""}.</p><div class="table-wrap"><div class="table-scroll"><table class="t" style="min-width:0"><thead><tr><th>Estabelecimento</th><th>Página</th><th>Ativação</th><th></th></tr></thead><tbody>
                ${(res.results || []).map((x) => x.ok ? `<tr><td>${esc(x.nome)}</td><td><a href="${esc(x.pagina)}" target="_blank" rel="noopener">abrir</a></td><td>${x.ativar ? copyBtn(x.ativar, "Copiar link") : "—"}</td><td>${x.mensagem && x.whatsapp ? `<a class="btn sm primary" href="${esc(wa(x.whatsapp, x.mensagem))}" target="_blank" rel="noopener">${I("brand:whatsapp", "sm")}Enviar</a>` : ""}</td></tr>` : `<tr><td>${esc(x.nome || "")}</td><td colspan="3"><span class="pill red">${esc(x.error)}</span></td></tr>`).join("")}</tbody></table></div></div>`;
              CF.toast(`${ok.length} páginas prontas.`); dl("prospeccao-links.csv", csv(res.results.filter((x) => x.ok), [["estabelecimento", "nome"], ["pagina", "pagina"], ["link_ativacao", "ativar"], ["whatsapp", "whatsapp"], ["mensagem", "mensagem"]]), "text/csv"); load();
            } catch (e) { CF.toast(e.message, "err"); } finally { prep.disabled = false; prep.innerHTML = `${I("sparkles", "sm")}Preparar selecionados`; }
          });
        } catch (e) { pb.innerHTML = `<p class="muted">${esc(e.message)}</p>`; }
      };
      $("#pb-go", v).addEventListener("click", search);
      load(); search();
    } }));

  route("/export", () => ({ title: "Exportar dados", sub: "Planilhas (CSV) e modelos (JSON) de tudo o que está na plataforma.", nav: "exp",
    html: `<div class="stack"><div class="grid g2" style="gap:16px"><section class="card"><div class="card-h"><h2>Negócios</h2><p>Todos os estabelecimentos com plano, uso e e-mail do dono.</p></div><div class="card-b row wrap" style="gap:8px"><button class="btn primary" id="x-biz">${I("download", "sm")}negocios.csv</button><button class="btn" id="x-bizj">${I("download", "sm")}negocios.json</button></div></section>
      <section class="card"><div class="card-h"><h2>Assinaturas</h2><p>Situação na Stripe, periodicidade, valor e próxima cobrança.</p></div><div class="card-b row wrap" style="gap:8px"><button class="btn primary" id="x-pay">${I("download", "sm")}assinaturas.csv</button></div></section>
      <section class="card"><div class="card-h"><h2>Clientes de um negócio</h2><p>Nome, contato, código do cartão, carimbos.</p></div><div class="card-b stack-sm" style="gap:8px"><select class="select" id="x-cb"><option>Carregando…</option></select><div><button class="btn primary" id="x-cust">${I("download", "sm")}clientes.csv</button></div></div></section>
      <section class="card"><div class="card-h"><h2>Modelos</h2><p>JSON com página, cartões e itens de cada negócio — para importar em outro.</p></div><div class="card-b stack-sm" style="gap:8px"><select class="select" id="x-mb"><option>Carregando…</option></select><div class="row wrap" style="gap:8px"><button class="btn primary" id="x-model">${I("download", "sm")}modelo.json</button><button class="btn" id="x-all">${I("download", "sm")}todos os modelos (.json)</button></div></div></section></div>${srcNote()}</div>`,
    async mount(v) { let items = []; try { items = (await A.api("businesses")).items || []; } catch (e) { CF.toast(e.message, "err"); }
      const opts = items.map((b) => `<option value="${esc(b.id)}" data-slug="${esc(b.slug)}">${esc(b.name)} (${esc(b.slug)})</option>`).join(""); $("#x-cb", v).innerHTML = opts; $("#x-mb", v).innerHTML = opts;
      const BC = [["negocio", "name"], ["slug", "slug"], ["email_dono", "owner_email"], ["plano", "plan"], ["teste", (r) => (r.trial ? "sim" : "não")], ["clientes", "customers"], ["carimbos_30d", "stamps_30d"], ["recompensas_30d", "redeemed_30d"], ["visitantes_30d", "visitors_30d"], ["google_nota", (r) => (r.gmaps && r.gmaps.nota) || ""], ["google_avaliacoes", (r) => (r.gmaps && r.gmaps.total_avaliacoes) || ""], ["chatbot", (r) => (r.forja ? r.forja.status : "")], ["criado_em", "created_at"]];
      $("#x-biz", v).addEventListener("click", () => dl("negocios.csv", csv(items, BC), "text/csv"));
      $("#x-bizj", v).addEventListener("click", () => dl("negocios.json", JSON.stringify(items, null, 2), "application/json"));
      $("#x-pay", v).addEventListener("click", async () => { const p = (await A.api("payments")).items || []; dl("assinaturas.csv", csv(p, [["negocio", "name"], ["email_dono", "owner_email"], ["plano", "plan"], ["assinatura", (r) => (r.billing && r.billing.status) || ""], ["periodicidade", (r) => (r.billing && r.billing.interval) || ""], ["valor_mes", (r) => monthlyOf(r.billing)], ["proxima_cobranca", (r) => (r.billing && r.billing.period_end) || ""], ["cancela_no_fim", (r) => (r.billing && r.billing.cancel_at_end ? "sim" : "não")], ["stripe_customer", (r) => (r.billing && r.billing.customer_id) || ""]]), "text/csv"); });
      $("#x-cust", v).addEventListener("click", async () => { const s = $("#x-cb", v); const rows = (await A.api("customers", { id: s.value })).items || []; dl(`clientes-${s.selectedOptions[0].dataset.slug}.csv`, csv(rows, [["nome", "name"], ["telefone", "phone"], ["email", "email"], ["aniversario", "birthday"], ["codigo", "code"], ["carimbos", "stamps"], ["total", "total"], ["ultimo_carimbo", "last"], ["cadastro", "created_at"]]), "text/csv"); });
      $("#x-model", v).addEventListener("click", async () => { const s = $("#x-mb", v); const r = await A.api("export", { id: s.value }); dl(`modelo-${s.selectedOptions[0].dataset.slug}.json`, JSON.stringify(r.model, null, 2), "application/json"); });
      $("#x-all", v).addEventListener("click", async () => { const all = []; for (const b of items) { try { all.push((await A.api("export", { id: b.id })).model); } catch (e) {} } dl("modelos.json", JSON.stringify(all, null, 2), "application/json"); }); } }));

  /* ============================================================ Forja · Chaves · Auditoria */
  route("/visitas", () => ({ title: "Roteiro de visitas", sub: "Acessos temporários, links de ativação e mensagens de WhatsApp para a visita. Só o superadmin vê esta tela.", nav: "visit",
    html: `<div class="stack"><section class="card"><div class="card-b" id="vr-box" style="padding:0"><p class="muted" style="padding:20px">Carregando…</p></div></section>${srcNote()}</div>`,
    async mount(v) { const box = $("#vr-box", v); try { const it = (await A.api("visit-route", { id: "itapema" })).item;
      if (!it) { box.innerHTML = `<p class="muted" style="padding:20px">Nenhum roteiro publicado ainda. No computador: <code>python tools/publicar_roteiro.py --producao</code>.</p>`; return; }
      const fr = document.createElement("iframe"); fr.title = it.title; fr.setAttribute("sandbox", "allow-scripts allow-same-origin allow-popups allow-popups-to-escape-sandbox allow-forms");
      fr.style.cssText = "width:100%;height:calc(100vh - 190px);min-height:560px;border:0;border-radius:inherit;background:#0d0d0d"; fr.srcdoc = it.html; box.innerHTML = ""; box.append(fr);
    } catch (e) { box.innerHTML = `<p style="padding:20px">${err(e.message === "forbidden" ? "Acesso restrito ao superadmin." : e.message)}</p>`; } } }));
  route("/forja", () => ({ title: "Chatbots (Forja)", sub: "Um bot por cliente, cada um no próprio Cloudflare.", nav: "forja", html: `<div class="stack"><section class="card"><div class="card-b" id="fj-list"><p class="muted">Carregando…</p></div></section>${srcNote()}</div>`,
    async mount(v) { try { const rows = ((await A.api("businesses")).items || []).filter((b) => b.forja); $("#fj-list", v).innerHTML = rows.length ? `<div class="table-wrap"><div class="table-scroll"><table class="t"><thead><tr><th>Negócio</th><th>Bot</th><th>Endereço</th><th>Plano do bot</th><th>Estado</th><th>Último contato</th><th></th></tr></thead><tbody>${rows.map((b) => `<tr><td><b>${esc(b.name)}</b></td><td>${esc(b.forja.name)}</td><td><a href="${esc(b.forja.base_url)}/admin" target="_blank" rel="noopener">${esc(b.forja.base_url.replace(/^https:\/\//, ""))}</a></td><td>${b.forja.tier === "pro" ? "Pro" : "Free"}</td><td>${forjaPill(b.forja)}</td><td>${esc(when(b.forja.last_seen_at, true))}</td><td><a class="btn sm" href="#/businesses/${esc(b.id)}?tab=forja">Abrir</a></td></tr>`).join("")}</tbody></table></div></div>` : `<p class="muted">Nenhum chatbot vinculado. Abra um negócio → aba Chatbot.</p>`; } catch (e) { $("#fj-list", v).innerHTML = err(e.message); } } }));
  route("/keys", () => ({ title: "Chaves e consumo", sub: "Saldo das chaves da SerpAPI (busca do Google Maps). Só com o servidor local — as chaves não saem deste computador.", nav: "keys", html: `<div class="stack"><section class="card"><div class="card-b" id="k-list"><p class="muted">Consultando…</p></div></section>${srcNote()}</div>`,
    async mount(v) { try { const d = await A.api("serp-status"); $("#k-list", v).innerHTML = `<div class="stat-inline" style="margin-bottom:16px"><div><b>${esc(String(d.total_restantes || 0))}</b><span>buscas restantes</span></div><div><b>${(d.chaves || []).length}</b><span>chaves</span></div></div><div class="table-wrap"><div class="table-scroll"><table class="t" style="min-width:0"><thead><tr><th>Chave</th><th>Plano</th><th>Usadas no mês</th><th>Restantes</th><th>Estado</th></tr></thead><tbody>${(d.chaves || []).map((c) => `<tr><td><code>${esc(c.chave)}</code></td><td>${esc(c.plano || "—")}</td><td>${esc(String(c.usadas_mes ?? "—"))}${c.limite_mes ? " / " + c.limite_mes : ""}</td><td><b>${esc(String(c.restantes ?? "—"))}</b></td><td>${c.ok ? `<span class="pill green">ok</span>` : `<span class="pill red" title="${esc(c.erro || "")}">erro</span>`}</td></tr>`).join("")}</tbody></table></div></div>`; } catch (e) { $("#k-list", v).innerHTML = err(e.message); } } }));
  route("/audit", () => ({ title: "Auditoria", sub: "Quem fez o quê no painel da plataforma.", nav: "audit", html: `<div class="stack"><section class="card"><div class="card-b"><ul class="audit" id="au" style="list-style:none;padding:0;margin:0"><li>Carregando…</li></ul></div></section>${srcNote()}</div>`,
    async mount(v) { const L = { set_plan: "trocou o plano", update_business: "editou dados do negócio", set_card: "salvou um cartão", delete_card: "excluiu um cartão", set_items: "salvou os itens da página", import_model: "aplicou um modelo", create_business: "criou um estabelecimento", set_nav: "salvou o menu do painel" };
      try { const rows = (await A.api("audit")).items || []; $("#au", v).innerHTML = rows.length ? rows.map((a) => `<li><small>${esc(when(a.at, true))}<br>${esc(a.by || "")}</small><span><b>${esc(L[a.action] || a.action)}</b>${a.business ? ` — ${esc(a.business)}` : ""}${a.details ? `<br><small>${esc(JSON.stringify(a.details).slice(0, 160))}</small>` : ""}</span></li>`).join("") : `<li class="muted">Nada registrado ainda.</li>`; } catch (e) { $("#au", v).innerHTML = `<li>${err(e.message)}</li>`; } } }));

  /* ============================================================ entrada: login quando há servidor */
  const loginScreen = (msg) => { $("#root").innerHTML = `<div class="login"><form class="card" id="lg"><div class="center"><img class="login-logo" src="../assets/img/seucliente-logo.svg" alt="${esc(CF.config.product)}" style="height:48px"><p class="muted" style="margin-top:14px"><b>Painel da plataforma</b><br>Entre com a conta de superadmin.</p></div><div class="field"><label for="lg-e">E-mail</label><input class="input" id="lg-e" type="email" required autocomplete="username" autofocus></div><div class="field"><label for="lg-p">Senha</label><input class="input" id="lg-p" type="password" required autocomplete="current-password"></div>${msg ? err(msg) : ""}<button class="btn primary lg block">Entrar</button><a class="small center" href="../">Voltar ao painel do lojista</a></form></div>`;
    $("#lg").addEventListener("submit", async (e) => { e.preventDefault(); try { await A.login($("#lg-e").value.trim(), $("#lg-p").value); start(); } catch (e2) { loginScreen(e2.message); } }); };
  async function start() {
    if (A.online) { await A.session(); if (!A.user) return loginScreen(); if (!(await A.isAdmin())) { $("#root").innerHTML = `<div class="login"><div class="card center"><h2>Acesso restrito</h2><p class="muted" style="margin:10px 0 16px">A conta <b>${esc(A.user.email)}</b> não é superadmin da plataforma.</p><div class="row" style="justify-content:center;gap:8px"><a class="btn" href="../">Painel do lojista</a><button class="btn primary" id="lg-out">Sair</button></div></div></div>`; $("#lg-out").addEventListener("click", async () => { await A.logout(); location.reload(); }); return; } }
    await render();
  }
  start();
})();
